insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'yhct-kham-108',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"yhct-kham-108","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Nam 48 tuổi đau cứng cổ vai gáy phải sau ngủ phòng điều hòa","setting":"chamcuu","level":"Trung bình","track":"yhct","mode":"dongtay","specialty":null,"demographics":{"age":48,"sex":"nam","patient_label":"Hoàng Văn Thịnh"},"presentation":{"intro":"Phòng châm cứu, Y học cổ truyền. Anh Thịnh là lập trình viên, ngồi máy tính nhiều giờ, đến khám vì đau cứng cổ vai gáy bên phải 3 tuần sau khi ngủ ở phòng điều hòa, quay cổ sang phải khó.","place":"Phòng châm cứu, Y học cổ truyền","clock":"17:20","night":false},"vitals":{"hr":76,"sbp":122,"dbp":78,"rr":16,"temperature_c":36.6,"spo2":99},"history":[{"question":"Đau ở đâu, xuất hiện thế nào, mức đau, kéo dài bao lâu, tăng hay giảm khi nào?","response":"Đau cứng cổ và vai phải, 3 tuần, đau 5 trên 10, tăng khi ngồi lâu và quay cổ phải, giảm khi chườm ấm."},{"question":"Đau có lan xuống cánh tay, cẳng tay, bàn tay không? Có tê, kiến bò, yếu tay, rơi đồ vật không?","response":"Đau chỉ lan ở vai, không xuống quá khuỷu, không tê, không yếu tay."},{"question":"Có đau ngực, khó thở, vã mồ hôi, đau lan lên cổ hàm hoặc cánh tay trái khi gắng sức không?","response":"Không có, không đau ngực, không khó thở."},{"question":"Có sốt, sụt cân, đau đêm dữ dội, tiền sử ung thư, chấn thương cổ, đi lại loạng choạng, rối loạn tiểu tiện không?","response":"Không có."},{"question":"Sợ gió lạnh, đau tăng khi trời lạnh, có đau đầu vùng chẩm, chóng mặt khi quay cổ không?","response":"Sợ gió lạnh, đau nhẹ vùng chẩm, không chóng mặt."},{"question":"Nghề nghiệp, tư thế ngồi, thời gian ngồi, tập thể dục, ngủ gối cao hay thấp?","response":"Ngồi máy tính 9 đến 10 giờ mỗi ngày, màn hình thấp, ít tập thể dục, gối cao."},{"question":"Đã dùng thuốc gì? Có bệnh dạ dày, thận, huyết áp, tim mạch không?","response":"Uống ibuprofen vài ngày thì đỡ ít. Không bệnh dạ dày, thận, không tăng huyết áp."},{"question":"Ăn ngủ, đại tiểu tiện, tinh thần?","response":"Ngủ kém do đau, ăn uống bình thường, hơi căng thẳng công việc."}],"examination":[{"group":"V","item":"Dáng, tư thế cổ","finding":"Cổ vai phải hơi nghiêng, vai phải nâng, đầu hơi đưa ra trước."},{"group":"V","item":"Lưỡi","finding":"Chất lưỡi nhạt, rêu trắng mỏng."},{"group":"M","item":"Giọng nói, hơi thở","finding":"Giọng nói bình thường."},{"group":"T","item":"Mạch","finding":"Mạch phù khẩn."},{"group":"K","item":"Sờ nắn cơ cổ vai gáy, tầm vận động","finding":"Co cứng cơ thang và nâng vai phải, điểm đau Kiên tỉnh và Phong trì, xoay cổ phải khoảng 50 độ, xoay trái 75 độ, gập duỗi hạn chế nhẹ."},{"group":"K","item":"Nghiệm pháp Spurling, kéo giãn cổ","finding":"Spurling âm tính, kéo giãn cổ không thay đổi triệu chứng."},{"group":"K","item":"Khám thần kinh chi trên","finding":"Phản xạ gân xương hai tay bình thường, sức cơ 5 trên 5, cảm giác bình thường, không dấu hiệu bệnh tủy."}],"investigations":[{"name":"X-quang cột sống cổ thẳng và nghiêng","duration_minutes":10,"result":"Mất đường cong sinh lý, gai xương nhỏ C5-C6, khe liên đốt hơi hẹp, không gãy, không tổn thương hủy xương."},{"name":"Điện tâm đồ","duration_minutes":10,"result":"Nhịp xoang 76 lần phút, không thiếu máu cơ tim."},{"name":"CRP, tốc độ máu lắng","duration_minutes":10,"result":"Bình thường."},{"name":"MRI cột sống cổ","duration_minutes":10,"result":"Không có chỉ định ở đau cổ cơ học chưa có dấu hiệu rễ hoặc tủy."},{"name":"CT cột sống cổ","duration_minutes":40,"result":"Không có chỉ định, phơi nhiễm bức xạ, chưa đổi hướng xử trí."}],"choices":{"diagnosis":{"ydx":["Thoát vị đĩa đệm cột sống cổ chèn ép rễ","Đau cổ cơ học do co cứng cơ, có thoái hóa cột sống cổ nhẹ, chưa có triệu chứng chèn ép rễ","Lao cột sống cổ","Bệnh lý tủy cổ do thoái hóa","Đau thắt ngực lan vai"],"bd":["Tý chứng thể Thống tý","Hiếp thống","Cảnh kiên thống","Hư lao","Tý chứng thể Hành tý"],"bc":["Biểu – Hư – Nhiệt","Biểu – Thực – Hàn","Biểu – Thực – Nhiệt","Lý – Hư – Hàn","Lý – Thực – Nhiệt"],"the":["Thấp nhiệt","Khí trệ huyết ứ","Can thận hư","Đàm thấp ngưng trệ","Phong hàn thấp tý"],"phap":["Bổ can thận, cường cân cốt","Khu phong tán hàn, thư cân hoạt lạc","Hoạt huyết hóa ứ, chỉ thống","Hóa đàm thông lạc","Thanh nhiệt lợi thấp"],"phuong":["Quyên tý thang","Tứ vật đào hồng","Độc hoạt tang ký sinh thang","Thân thống trục ứ thang","Cát căn thang"],"huyet":["Đại chùy","Phong trì","Kiên trung du","Hậu khê","Dũng tuyền","Thái dương","Kiên tỉnh","Thận du","Thượng tinh"]},"actions":["Châm sâu hoặc châm thẳng sâu vào Kiên tỉnh, Phong phủ, Á môn","Chườm ấm vùng cổ vai, chỉnh tư thế làm việc (màn hình ngang tầm mắt, gối vừa), nghỉ 5 phút mỗi 30 đến 45 phút, tập vận động và giãn cơ cổ nhẹ","Chụp MRI và CT cột sống cổ ngay","Châm cứu Phong trì, Kiên tỉnh, Đại chùy, Kiên trung du, Hậu khê, kèm cứu ấm hoặc xoa bóp bấm huyệt vùng cổ vai, lưu kim 20 phút","Thuốc giảm đau chống viêm ngắn ngày (ibuprofen 400 mg sau ăn mỗi 8 giờ, không quá 5 đến 7 ngày) hoặc thuốc bôi, sau khi đã hỏi tiền sử dạ dày, thận","Chụp X-quang cột sống cổ thẳng nghiêng và làm điện tâm đồ","Nắn chỉnh, bẻ cổ cường độ mạnh hoặc xoay cổ đột ngột","Cát căn thang sắc uống mỗi ngày một thang, dùng ngắn ngày: Cát căn 12 g, Ma hoàng 6 g, Quế chi 6 g, Bạch thược 6 g, Chích thảo 6 g, Sinh khương 9 g, Đại táo 3 quả; thận trọng Ma hoàng nếu có tăng huyết áp, tim mạch","Hỏi và khám tìm dấu hiệu báo động: đau lan quá khuỷu, tê yếu tay, rối loạn đi, tiểu tiện, sốt, sụt cân, đau ngực khi gắng sức"]}}'::jsonb,
  '56117db2c34770a1fc7586fad43189814fdf2bc006a7c4ebc5efc76843c0dd4d'
)
