hóa","credit":"none"},{"text":"Đau thắt ngực lan vai","credit":"none"},{"text":"Lao cột sống cổ","credit":"none"}],"bd":[{"text":"Cảnh kiên thống","credit":"full"},{"text":"Tý chứng thể Hành tý","credit":"none"},{"text":"Tý chứng thể Thống tý","credit":"none"},{"text":"Hư lao","credit":"none"},{"text":"Hiếp thống","credit":"none"}],"bc":[{"text":"Biểu – Thực – Hàn","credit":"full"},{"text":"Lý – Thực – Nhiệt","credit":"none"},{"text":"Biểu – Hư – Nhiệt","credit":"none"},{"text":"Lý – Hư – Hàn","credit":"none"},{"text":"Biểu – Thực – Nhiệt","credit":"none"}],"the":[{"text":"Phong hàn thấp tý","credit":"full"},{"text":"Khí trệ huyết ứ","credit":"none"},{"text":"Can thận hư","credit":"none"},{"text":"Thấp nhiệt","credit":"none"},{"text":"Đàm thấp ngưng trệ","credit":"none"}],"phap":[{"text":"Khu phong tán hàn, thư cân hoạt lạc","credit":"full"},{"text":"Hoạt huyết hóa ứ, chỉ thống","credit":"none"},{"text":"Bổ can thận, cường cân cốt","credit":"none"},{"text":"Thanh nhiệt lợi thấp","credit":"none"},{"text":"Hóa đàm thông lạc","credit":"none"}],"phuong":[{"text":"Cát căn thang","credit":"full"},{"text":"Quyên tý thang","credit":"none"},{"text":"Độc hoạt tang ký sinh thang","credit":"none"},{"text":"Thân thống trục ứ thang","credit":"none"},{"text":"Tứ vật đào hồng","credit":"none"}],"huyet":[{"text":"Phong trì","credit":"full"},{"text":"Kiên tỉnh","credit":"full"},{"text":"Đại chùy","credit":"full"},{"text":"Kiên trung du","credit":"full"},{"text":"Hậu khê","credit":"full"},{"text":"Thái dương","credit":"none"},{"text":"Dũng tuyền","credit":"none"},{"text":"Thận du","credit":"none"},{"text":"Thượng tinh","credit":"none"}]},"action_options":[{"text":"Hỏi và khám tìm dấu hiệu báo động: đau lan quá khuỷu, tê yếu tay, rối loạn đi, tiểu tiện, sốt, sụt cân, đau ngực khi gắng sức","time_minutes":5,"grade":"recommended","rationale":"Phát hiện bệnh rễ, bệnh tủy, nhiễm trùng, u, bệnh tim."},{"text":"Chụp X-quang cột sống cổ thẳng nghiêng và làm điện tâm đồ","time_minutes":30,"grade":"recommended","rationale":"Đánh giá thoái hóa; loại trừ đau thắt ngực lan vai ở nam 48 tuổi."},{"text":"Chườm ấm vùng cổ vai, chỉnh tư thế làm việc (màn hình ngang tầm mắt, gối vừa), nghỉ 5 phút mỗi 30 đến 45 phút, tập vận động và giãn cơ cổ nhẹ","time_minutes":10,"grade":"recommended","rationale":"Điều trị nền cho đau cổ cơ học."},{"text":"Thuốc giảm đau chống viêm ngắn ngày (ibuprofen 400 mg sau ăn mỗi 8 giờ, không quá 5 đến 7 ngày) hoặc thuốc bôi, sau khi đã hỏi tiền sử dạ dày, thận","time_minutes":3,"grade":"recommended","rationale":"Giảm đau, tạo điều kiện vận động."},{"text":"Cát căn thang sắc uống mỗi ngày một thang, dùng ngắn ngày: Cát căn 12 g, Ma hoàng 6 g, Quế chi 6 g, Bạch thược 6 g, Chích thảo 6 g, Sinh khương 9 g, Đại táo 3 quả; thận trọng Ma hoàng nếu có tăng huyết áp, tim mạch","time_minutes":10,"grade":"recommended","rationale":"Khu phong tán hàn, giải cơ."},{"text":"Châm cứu Phong trì, Kiên tỉnh, Đại chùy, Kiên trung du, Hậu khê, kèm cứu ấm hoặc xoa bóp bấm huyệt vùng cổ vai, lưu kim 20 phút","time_minutes":25,"grade":"recommended","rationale":"Khu phong tán hàn, thư cân hoạt lạc; châm Phong trì, Kiên tỉnh đúng hướng và độ sâu."},{"text":"Chụp MRI và CT cột sống cổ ngay","time_minutes":60,"grade":"waste","rationale":"Chưa có chỉ định ở đau cổ cơ học không dấu hiệu rễ, tủy."},{"text":"Nắn chỉnh, bẻ cổ cường độ mạnh hoặc xoay cổ đột ngột","time_minutes":3,"grade":"harmful","rationale":"Nguy cơ bóc tách động mạch đốt sống, chèn ép tủy."},{"text":"Châm sâu hoặc châm thẳng sâu vào Kiên tỉnh, Phong phủ, Á môn","time_minutes":3,"grade":"harmful","rationale":"Nguy cơ tràn khí màng phổi, tổn thương hành tủy."}],"teaching_explanation":"Đau cổ vai gáy ở người ngồi máy tính nhiều giờ, khởi phát sau lạnh, không lan quá khuỷu, Spurling âm tính, khám thần kinh bình thường là đau cổ cơ học; chưa cần MRI. Ở nam trên 45 tuổi đau vai cổ cần nghĩ bệnh tim khi đau gắng sức, khó thở. Thể Phong hàn thấp tý: sợ gió lạnh, đau cứng cổ, chườm ấm đỡ, lưỡi nhạt rêu trắng mỏng, mạch phù khẩn, dùng Cát căn thang. Châm Kiên tỉnh, Phong phủ, Á môn phải đúng độ sâu; không bẻ cổ mạnh."}'::jsonb,
