  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-noi-tiet-003","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Mệt mỏi, sụt cân và sạm da","setting":"giuong","level":"Trung bình","track":"noi","mode":"tay","specialty":null,"demographics":{"age":38,"sex":"nữ","patient_label":"Người bệnh A"},"presentation":{"intro":"Người bệnh đến khám vì mệt kéo dài, chán ăn, sụt cân, chóng mặt khi đứng và da sạm dần.","place":null,"clock":null,"night":false},"vitals":{"hr":92,"sbp":92,"dbp":60,"rr":18,"temperature_c":36.7,"spo2":98},"history":[{"question":"Tình trạng mệt và sụt cân xuất hiện từ khi nào?","response":"Mệt tăng dần nhiều tháng, chán ăn và sút cân không chủ ý."},{"question":"Có chóng mặt khi đứng hoặc thèm ăn mặn không?","response":"Có chóng mặt khi thay đổi tư thế và gần đây thích thức ăn mặn hơn."},{"question":"Có nôn, đau bụng hoặc tiêu chảy kéo dài không?","response":"Không nôn, thỉnh thoảng buồn nôn nhẹ, không tiêu chảy kéo dài."},{"question":"Có dùng glucocorticoid kéo dài hoặc vừa ngừng thuốc steroid không?","response":"Không dùng glucocorticoid kéo dài."}],"examination":[{"group":"K","item":"Quan sát da và niêm mạc","finding":"Tăng sắc tố da rõ ở nếp gấp bàn tay và vùng niêm mạc miệng."},{"group":"K","item":"Đánh giá huyết áp tư thế","finding":"Có choáng váng khi đứng, gợi ý giảm thể tích tuần hoàn."},{"group":"K","item":"Khám tuyến giáp","finding":"Không thấy bướu giáp rõ."},{"group":"K","item":"Khám bụng","finding":"Bụng mềm, không phản ứng thành bụng."}],"investigations":[{"name":"Cortisol huyết thanh buổi sáng","duration_minutes":10,"result":"Giảm rõ."},{"name":"ACTH huyết tương","duration_minutes":10,"result":"Tăng."},{"name":"Natri và kali huyết thanh","duration_minutes":10,"result":"Hạ natri máu kèm tăng kali máu."},{"name":"Nghiệm pháp kích thích corticotropin","duration_minutes":15,"result":"Cortisol không đạt đáp ứng bình thường."}],"choices":{"diagnosis":{"ydx":["Cường giáp","Suy thượng thận nguyên phát","Suy thượng thận trung ương","Suy giáp nguyên phát"]},"actions":["Chờ kết quả nghiệm pháp kích thích mới cho hydrocortisone dù người bệnh tụt huyết áp, nghi khủng hoảng thượng thận","Làm nghiệm pháp kích thích corticotropin khi tình trạng cho phép","Điều trị thay thế glucocorticoid khi đã xác định suy thượng thận nguyên phát","Bổ sung mineralocorticoid khi xác nhận thiếu aldosterone","Dùng dexamethasone dài hạn làm lựa chọn thay thế thường quy"]}}'::jsonb,
