values (
  'noi-noi-tiet-003',
  '{"schema_version":"1.0.0","case_id":"noi-noi-tiet-003","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-noi-noi-tiet-003-1","resource_type":"other","source":"Endocrine Society, Diagnosis and Treatment of Primary Adrenal Insufficiency, 2016: https://www.endocrine.org/clinical-practice-guidelines/primary-adrenal-insufficiency . Trích: “standard dose (250 μg for adults ... ) iv corticotropin stimulation”; “hydrocortisone (15–25 mg) ... in two or three divided oral doses per day”; “fludrocortisone (starting dose, 50–100 μg in adults)”.","title":"Endocrine Society, Diagnosis and Treatment of Primary Adrenal Insufficiency, 2016: https://www.endocrine.org/clinical-practice-guidelines/primary-adrenal-insufficiency . Trích: “standard dose (250 μg for adults ... ) iv corticotropin stimulation”; “hydrocortisone (15–25 mg) ... in two or three divided oral doses per day”; “fludrocortisone (starting dose, 50–100 μg in adults)”.","organization":null,"year_version":null,"citation":"Endocrine Society, Diagnosis and Treatment of Primary Adrenal Insufficiency, 2016: https://www.endocrine.org/clinical-practice-guidelines/primary-adrenal-insufficiency . Trích: “standard dose (250 μg for adults ... ) iv corticotropin stimulation”; “hydrocortisone (15–25 mg) ... in two or three divided oral doses per day”; “fludrocortisone (starting dose, 50–100 μg in adults)”.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,3],"examination_essential_indices":[0,1,2],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"}],"diagnosis_options":{"ydx":[{"text":"Suy thượng thận nguyên phát","credit":"full"},{"text":"Suy giáp nguyên phát","credit":"none"},{"text":"Cường giáp","credit":"none"},{"text":"Suy thượng thận trung ương","credit":"none"}]},"action_options":[{"text":"Làm nghiệm pháp kích thích corticotropin khi tình trạng cho phép","time_minutes":2,"grade":"recommended","rationale":"Endocrine Society khuyến cáo nghiệm pháp corticotropin để xác nhận chẩn đoán."},{"text":"Điều trị thay thế glucocorticoid khi đã xác định suy thượng thận nguyên phát","time_minutes":2,"grade":"recommended","rationale":"Hydrocortisone là lựa chọn chuẩn cho điều trị thay thế."},{"text":"Bổ sung mineralocorticoid khi xác nhận thiếu aldosterone","time_minutes":2,"grade":"recommended","rationale":"Fludrocortisone được khuyến cáo ở người thiếu aldosterone."},{"text":"Dùng dexamethasone dài hạn làm lựa chọn thay thế thường quy","time_minutes":0,"grade":"waste","rationale":"Endocrine Society không ưu tiên dexamethasone do khó chỉnh liều và nguy cơ tác dụng phụ."},{"text":"Chờ kết quả nghiệm pháp kích thích mới cho hydrocortisone dù người bệnh tụt huyết áp, nghi khủng hoảng thượng thận","time_minutes":0,"grade":"harmful","rationale":"Khi nghi khủng hoảng thượng thận, điều trị glucocorticoid và bù dịch không được trì hoãn để chờ xét nghiệm."}],"teaching_explanation":"Suy thượng thận nguyên phát cần nghĩ đến khi mệt, sụt cân, hạ huyết áp, tăng sắc tố, hạ natri và tăng kali. Nếu người bệnh không trong cơn suy thượng thận cấp, nghiệm pháp kích thích corticotropin giúp xác nhận chẩn đoán."}'::jsonb,
  '58f4ebda9661afa071806d9698d6936390eb7eb9e5d2178b401aee03ba20c4c4'
)
