values (
  'noi-huyet-hoc-002',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-huyet-hoc-002","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Xuất huyết dưới da và giảm tiểu cầu đơn độc","setting":"giuong","level":"Trung bình","track":"noi","mode":"tay","specialty":null,"demographics":{"age":34,"sex":"nữ","patient_label":"Người bệnh B"},"presentation":{"intro":"Người bệnh đến khám vì xuất hiện nhiều chấm xuất huyết ở hai chân và dễ bầm tím.","place":null,"clock":null,"night":false},"vitals":{"hr":80,"sbp":112,"dbp":72,"rr":17,"temperature_c":36.6,"spo2":99},"history":[{"question":"Có chảy máu mũi, chảy máu chân răng hoặc rong kinh không?","response":"Có chảy máu chân răng nhẹ và kinh nguyệt nhiều hơn bình thường."},{"question":"Gần đây có dùng thuốc mới, heparin hoặc thuốc chống kết tập tiểu cầu không?","response":"Không dùng các thuốc trên."},{"question":"Có sốt kéo dài, sụt cân hoặc nổi hạch không?","response":"Không sốt kéo dài, không sụt cân, không tự phát hiện hạch."},{"question":"Có tiền sử bệnh gan, bệnh tự miễn hoặc nhiễm virus gần đây không?","response":"Chưa ghi nhận bệnh gan hay bệnh tự miễn."}],"examination":[{"group":"K","item":"Khám da","finding":"Nhiều chấm xuất huyết và mảng bầm nhỏ ở hai chi dưới."},{"group":"K","item":"Khám niêm mạc","finding":"Có điểm xuất huyết niêm mạc miệng, không chảy máu ồ ạt."},{"group":"K","item":"Khám gan lách","finding":"Không ghi nhận gan lách to rõ."},{"group":"K","item":"Khám hạch ngoại vi","finding":"Không phát hiện hạch ngoại vi bất thường."}],"investigations":[{"name":"Công thức máu","duration_minutes":10,"result":"Tiểu cầu 22×10^9/L; hemoglobin và bạch cầu không giảm đáng kể."},{"name":"Phết máu ngoại biên","duration_minutes":10,"result":"Không thấy blast; không có kết cụm tiểu cầu giả tạo."},{"name":"Chức năng gan","duration_minutes":10,"result":"Không gợi ý bệnh gan mất bù."},{"name":"Xét nghiệm nguyên nhân thứ phát theo chỉ định","duration_minutes":10,"result":"Không phát hiện nguyên nhân thứ phát trong tình huống mô phỏng."}],"choices":{"diagnosis":{"ydx":["Bạch cầu cấp","Suy tủy xương","Giảm tiểu cầu miễn dịch nguyên phát","Ban xuất huyết giảm tiểu cầu huyết khối"]},"actions":["Đánh giá mức độ chảy máu, thuốc đang dùng và nguyên nhân giảm tiểu cầu thứ phát","Nếu cần điều trị ban đầu, áp dụng lựa chọn theo ASH 2026 và điều kiện người bệnh","Tiêm bắp thuốc giảm đau hoặc kháng sinh khi tiểu cầu còn 22×10^9/L","Cắt lách ngay khi mới chẩn đoán","Hội chẩn Huyết học để quyết định điều trị thay vì chỉ quan sát"]}}'::jsonb,
  'f2360b7679fc9251f3390bd53958d5b0062b3347a717d536364f63389aafe67b'
)
on conflict (case_id) do update set
