values (
  'noi-huyet-hoc-002',
  '{"schema_version":"1.0.0","case_id":"noi-huyet-hoc-002","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-noi-huyet-hoc-002-1","resource_type":"other","source":"American Society of Hematology, Summary of Changes to the 2026 Updated Recommendations: https://www.hematology.org/-/media/hematology/files/clinicians/guidelines/ash-itp-summary-of-changes_20260824.pdf . Trích: “Adults, newly dx ITP, platelets <30×10⁹/L, asymptomatic/minor bleeding”; “The threshold for initiating therapy has not been updated.”","title":"American Society of Hematology, Summary of Changes to the 2026 Updated Recommendations: https://www.hematology.org/-/media/hematology/files/clinicians/guidelines/ash-itp-summary-of-changes_20260824.pdf . Trích: “Adults, newly dx ITP, platelets <30×10⁹/L, asymptomatic/minor bleeding”; “The threshold for initiating therapy has not been updated.”","organization":null,"year_version":null,"citation":"American Society of Hematology, Summary of Changes to the 2026 Updated Recommendations: https://www.hematology.org/-/media/hematology/files/clinicians/guidelines/ash-itp-summary-of-changes_20260824.pdf . Trích: “Adults, newly dx ITP, platelets <30×10⁹/L, asymptomatic/minor bleeding”; “The threshold for initiating therapy has not been updated.”","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-noi-huyet-hoc-002-2","resource_type":"other","source":"American Society of Hematology, 2026 ITP Visual Summary: https://www.hematology.org/-/media/hematology/files/clinicians/guidelines/ash-cpg-itp-guidelines-visual-summary-0824.pdf . Trích: “Suggests rituximab + corticosteroids (with or without IVIG)” và “Suggests thrombopoietic agent + corticosteroids (with or without IVIG)”.","title":"American Society of Hematology, 2026 ITP Visual Summary: https://www.hematology.org/-/media/hematology/files/clinicians/guidelines/ash-cpg-itp-guidelines-visual-summary-0824.pdf . Trích: “Suggests rituximab + corticosteroids (with or without IVIG)” và “Suggests thrombopoietic agent + corticosteroids (with or without IVIG)”.","organization":null,"year_version":null,"citation":"American Society of Hematology, 2026 ITP Visual Summary: https://www.hematology.org/-/media/hematology/files/clinicians/guidelines/ash-cpg-itp-guidelines-visual-summary-0824.pdf . Trích: “Suggests rituximab + corticosteroids (with or without IVIG)” và “Suggests thrombopoietic agent + corticosteroids (with or without IVIG)”.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2],"examination_essential_indices":[0,1,2,3],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"neutral"},{"index":3,"role":"essential"}],"diagnosis_options":{"ydx":[{"text":"Giảm tiểu cầu miễn dịch nguyên phát","credit":"full"},{"text":"Ban xuất huyết giảm tiểu cầu huyết khối","credit":"none"},{"text":"Suy tủy xương","credit":"none"},{"text":"Bạch cầu cấp","credit":"none"}]},"action_options":[{"text":"Đánh giá mức độ chảy máu, thuốc đang dùng và nguyên nhân giảm tiểu cầu thứ phát","time_minutes":2,"grade":"recommended","rationale":"ITP là chẩn đoán loại trừ và quyết định điều trị phải cá thể hóa."},{"text":"Hội chẩn Huyết học để quyết định điều trị thay vì chỉ quan sát","time_minutes":2,"grade":"recommended","rationale":"ASH giữ ngưỡng dưới 30×10^9/L cho người lớn mới chẩn đoán, không triệu chứng hoặc chảy máu nhẹ, cần điều trị hơn là chỉ quan sát."},{"text":"Nếu cần điều trị ban đầu, áp dụng lựa chọn theo ASH 2026 và điều kiện người bệnh","time_minutes":2,"grade":"recommended","rationale":"ASH 2026 cập nhật lựa chọn điều trị ban đầu, ưu tiên quyết định chung."},{"text":"Cắt lách ngay khi mới chẩn đoán","time_minutes":0,"grade":"waste","rationale":"Không phải lựa chọn điều trị đầu tay cho ITP mới chẩn đoán."},{"text":"Tiêm bắp thuốc giảm đau hoặc kháng sinh khi tiểu cầu còn 22×10^9/L","time_minutes":0,"grade":"harmful","rationale":"Tiêm bắp khi giảm tiểu cầu nặng có nguy cơ tụ máu cơ; nên tránh đường tiêm này."}],"teaching_explanation":"ITP thường biểu hiện bằng giảm tiểu cầu đơn độc và xuất huyết da-niêm mạc sau khi loại trừ nguyên nhân khác. Ngưỡng tiểu cầu chỉ là một phần của quyết định; mức chảy máu, bệnh kèm, thuốc và ưu tiên người bệnh đều quan trọng."}'::jsonb,
  '143bb94d1d1e0079a689ae534473b7b95157bba85aa0a89b624062d808888cc6'
)
