  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-than-004","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Bệnh thận mạn kèm albumin niệu nhiều","setting":"giuong","level":"Trung bình","track":"noi","mode":"tay","specialty":null,"demographics":{"age":58,"sex":"nam","patient_label":"Người bệnh C"},"presentation":{"intro":"Người bệnh được phát hiện chức năng thận giảm kéo dài khi theo dõi tăng huyết áp.","place":null,"clock":null,"night":false},"vitals":{"hr":76,"sbp":138,"dbp":82,"rr":17,"temperature_c":36.5,"spo2":98},"history":[{"question":"Đã từng có kết quả creatinin hoặc eGFR bất thường trước đây chưa?","response":"Các lần xét nghiệm cách nhau hơn ba tháng đều ghi nhận chức năng thận giảm."},{"question":"Có phù, tiểu bọt hoặc tiểu máu không?","response":"Có tiểu bọt, phù mắt cá chân nhẹ cuối ngày, không thấy tiểu máu đại thể."},{"question":"Có dùng NSAID hoặc thuốc không rõ nguồn gốc kéo dài không?","response":"Thỉnh thoảng tự dùng thuốc giảm đau khi đau lưng."},{"question":"Có tiền sử đái tháo đường hoặc tăng huyết áp không?","response":"Có tăng huyết áp nhiều năm."}],"examination":[{"group":"K","item":"Khám phù","finding":"Phù nhẹ hai mắt cá chân."},{"group":"K","item":"Khám tim phổi","finding":"Chưa ghi nhận dấu sung huyết phổi."},{"group":"K","item":"Khám bụng và hố thận","finding":"Không đau hông lưng, không cầu bàng quang."},{"group":"K","item":"Đánh giá tình trạng dịch","finding":"Không có dấu mất nước cấp."}],"investigations":[{"name":"Creatinin huyết thanh và eGFR","duration_minutes":10,"result":"eGFR 42 mL/phút/1,73 m², giảm dai dẳng trên ba tháng."},{"name":"Tỷ số albumin/creatinin niệu","duration_minutes":10,"result":"ACR 420 mg/g."},{"name":"Điện giải đồ","duration_minutes":10,"result":"Chưa có rối loạn điện giải nặng."},{"name":"Siêu âm thận-tiết niệu","duration_minutes":15,"result":"Không ghi nhận tắc nghẽn đường niệu."}],"choices":{"diagnosis":{"ydx":["Bệnh thận mạn có albumin niệu mức cao","Tổn thương thận cấp trước thận","Viêm bể thận cấp","Sỏi niệu quản gây tắc nghẽn cấp"]},"actions":["Cân nhắc SGLT2i theo tiêu chuẩn KDIGO","Ngừng theo dõi albumin niệu nếu creatinin ổn định","Tiếp tục tự dùng thuốc chống viêm không steroid kéo dài để giảm đau lưng","Dùng ACEi hoặc ARB khi có chỉ định và theo dõi creatinin, kali sau khi bắt đầu hoặc tăng liều","Phân tầng bệnh thận mạn theo eGFR và albumin niệu, đồng thời tìm nguyên nhân nền"]}}'::jsonb,
  '076bca1a1adf8c7ac5266f837e9c87e42d9694c4d26fc7eb84942d2406948dce'
)
