ull,"citation":"KDIGO CKD Evaluation and Management page, current status 2026: https://kdigo.org/guidelines/ckd-evaluation-and-management/ . Trích: “KDIGO 2024 ... remains the current global standard”.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3],"examination_essential_indices":[0,1,3],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"}],"diagnosis_options":{"ydx":[{"text":"Bệnh thận mạn có albumin niệu mức cao","credit":"full"},{"text":"Tổn thương thận cấp trước thận","credit":"none"},{"text":"Viêm bể thận cấp","credit":"none"},{"text":"Sỏi niệu quản gây tắc nghẽn cấp","credit":"none"}]},"action_options":[{"text":"Phân tầng bệnh thận mạn theo eGFR và albumin niệu, đồng thời tìm nguyên nhân nền","time_minutes":2,"grade":"recommended","rationale":"KDIGO phân loại CKD theo GFR và albumin niệu."},{"text":"Dùng ACEi hoặc ARB khi có chỉ định và theo dõi creatinin, kali sau khi bắt đầu hoặc tăng liều","time_minutes":2,"grade":"recommended","rationale":"KDIGO yêu cầu theo dõi sau thay đổi RASi."},{"text":"Cân nhắc SGLT2i theo tiêu chuẩn KDIGO","time_minutes":2,"grade":"recommended","rationale":"Người bệnh có eGFR và ACR nằm trong nhóm được khuyến cáo SGLT2i."},{"text":"Ngừng theo dõi albumin niệu nếu creatinin ổn định","time_minutes":0,"grade":"waste","rationale":"Albumin niệu và GFR đều có giá trị theo dõi nguy cơ CKD."},{"text":"Tiếp tục tự dùng thuốc chống viêm không steroid kéo dài để giảm đau lưng","time_minutes":0,"grade":"harmful","rationale":"NSAID kéo dài làm giảm GFR và tăng nguy cơ tổn thương thận cấp trên nền CKD; cần tránh."}],"teaching_explanation":"CKD cần xác định tính mạn và phân tầng đồng thời theo GFR cùng albumin niệu. Điều trị bảo vệ thận tập trung vào nguyên nhân, kiểm soát huyết áp, RASi khi phù hợp và SGLT2i ở các nhóm có bằng chứng lợi ích."}'::jsonb,
