  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-co-xuong-khop-001","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Đau và sưng nhiều khớp nhỏ hai bàn tay","setting":"giuong","level":"Trung bình","track":"noi","mode":"tay","specialty":null,"demographics":{"age":46,"sex":"nữ","patient_label":"Người bệnh D"},"presentation":{"intro":"Người bệnh đến khám vì đau và sưng đối xứng các khớp bàn-ngón và liên đốt gần, cứng khớp buổi sáng kéo dài.","place":null,"clock":null,"night":false},"vitals":{"hr":78,"sbp":116,"dbp":72,"rr":17,"temperature_c":36.7,"spo2":99},"history":[{"question":"Cứng khớp buổi sáng kéo dài bao lâu và có đỡ khi vận động không?","response":"Cứng khớp kéo dài hơn một giờ, đỡ dần khi vận động."},{"question":"Triệu chứng đã kéo dài bao lâu?","response":"Đau và sưng khớp tiến triển nhiều tuần, chưa tự hết."},{"question":"Có đau lưng kiểu viêm, vảy nến hoặc viêm mắt không?","response":"Không ghi nhận."},{"question":"Có sốt, sụt cân hoặc nhiễm trùng gần đây không?","response":"Không sốt, không có bệnh nhiễm trùng gần đây."}],"examination":[{"group":"K","item":"Khám khớp bàn-ngón và liên đốt gần","finding":"Nhiều khớp sưng đau đối xứng hai bàn tay."},{"group":"K","item":"Khám khớp liên đốt xa","finding":"Không phải vị trí tổn thương nổi bật."},{"group":"K","item":"Đánh giá biến dạng khớp","finding":"Chưa có biến dạng cố định."},{"group":"K","item":"Khám ngoài khớp","finding":"Chưa ghi nhận nốt dưới da hoặc biểu hiện cơ quan khác."}],"investigations":[{"name":"RF","duration_minutes":10,"result":"Dương tính."},{"name":"Anti-CCP","duration_minutes":10,"result":"Dương tính mạnh."},{"name":"CRP hoặc tốc độ lắng máu","duration_minutes":10,"result":"Tăng, phù hợp tình trạng viêm hoạt động."},{"name":"X-quang bàn tay và cổ tay","duration_minutes":15,"result":"Chưa thấy phá hủy khớp nặng; dùng làm mốc theo dõi ban đầu."}],"choices":{"diagnosis":{"ydx":["Viêm khớp vảy nến","Gout mạn","Viêm khớp dạng thấp giai đoạn sớm","Thoái hóa khớp bàn tay"]},"actions":["Chỉ dùng thuốc giảm đau và trì hoãn DMARD cho tới khi có biến dạng","Dùng glucocorticoid liều cao kéo dài làm điều trị duy nhất, không khởi DMARD","Áp dụng tiêu chuẩn ACR/EULAR và loại trừ chẩn đoán khác giải thích viêm màng hoạt dịch","Khởi DMARD sớm; ưu tiên methotrexate đơn trị ở người chưa dùng DMARD có hoạt tính bệnh vừa-cao nếu không chống chỉ định","Theo chiến lược treat-to-target và đánh giá đáp ứng định kỳ"]}}'::jsonb,
