values (
  'noi-co-xuong-khop-001',
  '{"schema_version":"1.0.0","case_id":"noi-co-xuong-khop-001","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-noi-co-xuong-khop-001-1","resource_type":"other","source":"ACR/EULAR 2010 Rheumatoid Arthritis Classification Criteria, PMID 20872595: https://pubmed.ncbi.nlm.nih.gov/20872595/ . Trích: “achievement of a total score of 6 or greater (of a possible 10)”.","title":"ACR/EULAR 2010 Rheumatoid Arthritis Classification Criteria, PMID 20872595: https://pubmed.ncbi.nlm.nih.gov/20872595/ . Trích: “achievement of a total score of 6 or greater (of a possible 10)”.","organization":null,"year_version":null,"citation":"ACR/EULAR 2010 Rheumatoid Arthritis Classification Criteria, PMID 20872595: https://pubmed.ncbi.nlm.nih.gov/20872595/ . Trích: “achievement of a total score of 6 or greater (of a possible 10)”.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-noi-co-xuong-khop-001-2","resource_type":"other","source":"2021 American College of Rheumatology Guideline for the Treatment of Rheumatoid Arthritis: https://pmc.ncbi.nlm.nih.gov/articles/PMC9273041/ . Trích: “Methotrexate monotherapy is strongly recommended over ... Hydroxychloroquine or sulfasalazine” cho người chưa dùng DMARD có hoạt tính vừa-cao; “weekly dose of at least 15 mg within 4 to 6 weeks”.","title":"2021 American College of Rheumatology Guideline for the Treatment of Rheumatoid Arthritis: https://pmc.ncbi.nlm.nih.gov/articles/PMC9273041/ . Trích: “Methotrexate monotherapy is strongly recommended over ... Hydroxychloroquine or sulfasalazine” cho người chưa dùng DMARD có hoạt tính vừa-cao; “weekly dose of at least 15 mg within 4 to 6 weeks”.","organization":null,"year_version":null,"citation":"2021 American College of Rheumatology Guideline for the Treatment of Rheumatoid Arthritis: https://pmc.ncbi.nlm.nih.gov/articles/PMC9273041/ . Trích: “Methotrexate monotherapy is strongly recommended over ... Hydroxychloroquine or sulfasalazine” cho người chưa dùng DMARD có hoạt tính vừa-cao; “weekly dose of at least 15 mg within 4 to 6 weeks”.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,3],"examination_essential_indices":[0,1,2],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"neutral"}],"diagnosis_options":{"ydx":[{"text":"Viêm khớp dạng thấp giai đoạn sớm","credit":"full"},{"text":"Thoái hóa khớp bàn tay","credit":"none"},{"text":"Gout mạn","credit":"none"},{"text":"Viêm khớp vảy nến","credit":"none"}]},"action_options":[{"text":"Áp dụng tiêu chuẩn ACR/EULAR và loại trừ chẩn đoán khác giải thích viêm màng hoạt dịch","time_minutes":2,"grade":"recommended","rationale":"Phân loại RA dựa trên viêm màng hoạt dịch và tổng điểm tiêu chuẩn."},{"text":"Khởi DMARD sớm; ưu tiên methotrexate đơn trị ở người chưa dùng DMARD có hoạt tính bệnh vừa-cao nếu không chống chỉ định","time_minutes":2,"grade":"recommended","rationale":"ACR 2021 ưu tiên methotrexate đơn trị."},{"text":"Theo chiến lược treat-to-target và đánh giá đáp ứng định kỳ","time_minutes":2,"grade":"recommended","rationale":"Mục tiêu là kiểm soát hoạt tính bệnh và phòng tổn thương khớp."},{"text":"Chỉ dùng thuốc giảm đau và trì hoãn DMARD cho tới khi có biến dạng","time_minutes":0,"grade":"waste","rationale":"Trì hoãn DMARD làm tăng nguy cơ tổn thương khớp không hồi phục."},{"text":"Dùng glucocorticoid liều cao kéo dài làm điều trị duy nhất, không khởi DMARD","time_minutes":0,"grade":"harmful","rationale":"Glucocorticoid kéo dài không thay được DMARD và có nhiều tác dụng phụ; ACR 2021 khuyến cáo hạn chế dùng kéo dài."}],"teaching_explanation":"Tiêu chuẩn ACR/EULAR 2010 phân loại RA xác định khi có viêm màng hoạt dịch ít nhất một khớp, không có chẩn đoán khác giải thích tốt hơn và tổng điểm từ 6/10 trở lên. DMARD nên được bắt đầu sớm."}'::jsonb,
