  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-than-kinh-003","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Run tay khi nghỉ kèm chậm vận động","setting":"giuong","level":"Dễ","track":"noi","mode":"tay","specialty":null,"demographics":{"age":64,"sex":"nam","patient_label":"Người bệnh E"},"presentation":{"intro":"Người bệnh đến khám vì run tay phải khi nghỉ, đi chậm và khó thực hiện các động tác tinh tế.","place":null,"clock":null,"night":false},"vitals":{"hr":72,"sbp":126,"dbp":76,"rr":16,"temperature_c":36.6,"spo2":98},"history":[{"question":"Run xuất hiện khi nghỉ hay khi làm động tác?","response":"Run rõ khi tay nghỉ, giảm khi chủ động sử dụng tay."},{"question":"Có cảm giác vận động chậm hoặc khó trở mình, cài nút áo không?","response":"Có chậm vận động và làm các động tác tinh tế lâu hơn trước."},{"question":"Có dùng thuốc chống loạn thần hoặc thuốc chẹn dopamine không?","response":"Không dùng."},{"question":"Có té ngã sớm, rối loạn vận nhãn hoặc tụt huyết áp tư thế nặng không?","response":"Chưa ghi nhận các đặc điểm không điển hình này."}],"examination":[{"group":"K","item":"Đánh giá vận động chủ ý","finding":"Có bradykinesia rõ hơn bên phải."},{"group":"K","item":"Khám trương lực cơ","finding":"Tăng trương lực kiểu cứng đờ bên phải."},{"group":"K","item":"Quan sát run","finding":"Run khi nghỉ ưu thế một bên."},{"group":"K","item":"Đánh giá dáng đi","finding":"Bước ngắn, giảm vung tay bên phải."}],"investigations":[{"name":"Đánh giá thần kinh bởi bác sĩ chuyên khoa","duration_minutes":10,"result":"Bệnh cảnh lâm sàng phù hợp hội chứng Parkinson."},{"name":"MRI não","duration_minutes":15,"result":"Không dùng thường quy để xác lập chẩn đoán Parkinson điển hình; cân nhắc khi cần phân biệt hội chứng Parkinson khác."},{"name":"123I-FP-CIT SPECT","duration_minutes":20,"result":"Chỉ cân nhắc khi không phân biệt được run vô căn với parkinsonism trên lâm sàng."},{"name":"PET não thường quy","duration_minutes":20,"result":"Không dùng để chẩn đoán phân biệt hội chứng Parkinson thường quy."}],"choices":{"diagnosis":{"ydx":["Bệnh lý tiểu não","Run vô căn","Parkinson do thuốc","Bệnh Parkinson"]},"actions":["Nếu chẩn đoán xác lập và triệu chứng vận động ảnh hưởng chất lượng cuộc sống, cân nhắc levodopa","Chuyển sớm người bệnh chưa điều trị đến bác sĩ chuyên khoa thần kinh/rối loạn vận động","Làm PET não thường quy để phân biệt hội chứng Parkinson","Chụp MRI để xác nhận Parkinson ở mọi người bệnh","Dùng metoclopramide hoặc haloperidol khi cần chống nôn hay trấn an"]}}'::jsonb,
  '3f207911c9ec409e26d8bb117d0c40aa5f3399191867442c2087daa9add10194'
)
