values (
  'noi-than-kinh-003',
  '{"schema_version":"1.0.0","case_id":"noi-than-kinh-003","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-noi-than-kinh-003-1","resource_type":"other","source":"NICE NG71 Parkinson''s disease in adults, Recommendations: https://www.nice.org.uk/guidance/ng71/chapter/Recommendations . Trích: “If Parkinson''s disease is suspected, refer people quickly and untreated to a specialist”; “Offer levodopa to people in the early stages of Parkinson''s disease whose motor symptoms impact on their quality of life”; “Do not use structural MRI to diagnose Parkinson''s disease”; “Consider 123I-FP-CIT ... SPECT for people with tremor if essential tremor cannot be clinically differentiated from parkinsonism.”","title":"NICE NG71 Parkinson''s disease in adults, Recommendations: https://www.nice.org.uk/guidance/ng71/chapter/Recommendations . Trích: “If Parkinson''s disease is suspected, refer people quickly and untreated to a specialist”; “Offer levodopa to people in the early stages of Parkinson''s disease whose motor symptoms impact on their quality of life”; “Do not use structural MRI to diagnose Parkinson''s disease”; “Consider 123I-FP-CIT ... SPECT for people with tremor if essential tremor cannot be clinically differentiated from parkinsonism.”","organization":null,"year_version":null,"citation":"NICE NG71 Parkinson''s disease in adults, Recommendations: https://www.nice.org.uk/guidance/ng71/chapter/Recommendations . Trích: “If Parkinson''s disease is suspected, refer people quickly and untreated to a specialist”; “Offer levodopa to people in the early stages of Parkinson''s disease whose motor symptoms impact on their quality of life”; “Do not use structural MRI to diagnose Parkinson''s disease”; “Consider 123I-FP-CIT ... SPECT for people with tremor if essential tremor cannot be clinically differentiated from parkinsonism.”","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3],"examination_essential_indices":[0,1,2,3],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"neutral"},{"index":2,"role":"neutral"},{"index":3,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Bệnh Parkinson","credit":"full"},{"text":"Run vô căn","credit":"none"},{"text":"Parkinson do thuốc","credit":"none"},{"text":"Bệnh lý tiểu não","credit":"none"}]},"action_options":[{"text":"Chuyển sớm người bệnh chưa điều trị đến bác sĩ chuyên khoa thần kinh/rối loạn vận động","time_minutes":2,"grade":"recommended","rationale":"NICE khuyến cáo chuyển nhanh và chưa điều trị khi nghi Parkinson."},{"text":"Nếu chẩn đoán xác lập và triệu chứng vận động ảnh hưởng chất lượng cuộc sống, cân nhắc levodopa","time_minutes":2,"grade":"recommended","rationale":"NICE khuyến cáo levodopa trong tình huống này."},{"text":"Chụp MRI để xác nhận Parkinson ở mọi người bệnh","time_minutes":0,"grade":"waste","rationale":"NICE không khuyến cáo MRI cấu trúc để chẩn đoán Parkinson."},{"text":"Làm PET não thường quy để phân biệt hội chứng Parkinson","time_minutes":0,"grade":"waste","rationale":"NICE không khuyến cáo PET ngoài nghiên cứu cho mục đích này."},{"text":"Dùng metoclopramide hoặc haloperidol khi cần chống nôn hay trấn an","time_minutes":0,"grade":"harmful","rationale":"Thuốc chẹn dopamine làm nặng thêm triệu chứng parkinson."}],"teaching_explanation":"Parkinson là chẩn đoán lâm sàng; các đặc điểm gợi ý gồm bradykinesia, cứng đờ và run khi nghỉ. Người bệnh nghi Parkinson nên được chuyển sớm khi chưa điều trị đến bác sĩ có chuyên môn về chẩn đoán phân biệt."}'::jsonb,
  '257305600b9287ec586935faf674e403ffb019cd93d9ab5e33c5d218ae5f6651'
)
