  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-tieu-hoa-011","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Nôn ra máu và đi cầu phân đen","setting":"giuong","level":"Trung bình","track":"noi","mode":"tay","specialty":null,"demographics":{"age":61,"sex":"nam","patient_label":"Người bệnh mô phỏng A"},"presentation":{"intro":"Người bệnh nằm giường Nội tiêu hóa vì nôn ra máu đỏ sẫm và đi cầu phân đen, kèm choáng váng.","place":null,"clock":null,"night":false},"vitals":{"hr":106,"sbp":98,"dbp":62,"rr":20,"temperature_c":36.7,"spo2":97},"history":[{"question":"Nôn máu bắt đầu khi nào, số lần và màu sắc ra sao?","response":"Khởi phát trong ngày nhập viện, nôn hai lần máu đỏ sẫm lẫn cục nhỏ."},{"question":"Phân có thay đổi màu sắc không?","response":"Đi cầu phân đen sệt, mùi khẳm từ sáng."},{"question":"Có dùng NSAID, aspirin, thuốc chống đông hoặc uống rượu không?","response":"Dùng ibuprofen nhiều ngày vì đau khớp, không dùng thuốc chống đông."},{"question":"Trước đây có loét dạ dày-tá tràng hoặc xuất huyết tiêu hóa không?","response":"Từng đau thượng vị tái diễn nhưng chưa nội soi."},{"question":"Có đau ngực, khó thở hoặc ngất không?","response":"Không đau ngực; có chóng mặt khi ngồi dậy nhưng chưa ngất."}],"examination":[{"group":"K","item":"Đánh giá toàn trạng và tưới máu ngoại vi","finding":"Da niêm nhợt, đầu chi hơi lạnh, tỉnh táo."},{"group":"K","item":"Khám bụng","finding":"Bụng mềm, ấn đau nhẹ vùng thượng vị, không phản ứng phúc mạc."},{"group":"K","item":"Thăm trực tràng","finding":"Có phân đen trên găng."},{"group":"K","item":"Khám tim phổi","finding":"Tim nhanh đều, phổi thông khí hai bên."}],"investigations":[{"name":"Công thức máu","duration_minutes":10,"result":"Hemoglobin 6,8 g/dL; tiểu cầu không giảm."},{"name":"Ure, creatinin và điện giải","duration_minutes":10,"result":"Ure tăng tương đối, creatinin chưa tăng rõ."},{"name":"Nhóm máu và phản ứng chéo","duration_minutes":10,"result":"Đã lấy mẫu chuẩn bị truyền máu."},{"name":"Nội soi dạ dày-tá tràng sau hồi sức","duration_minutes":20,"result":"Ổ loét tá tràng có dấu xuất huyết nguy cơ cao cần điều trị nội soi."}],"choices":{"diagnosis":{"ydx":["Viêm tụy cấp","Xuất huyết tiêu hóa trên do loét dạ dày-tá tràng","Tắc ruột cơ học","Xuất huyết tiêu hóa dưới do túi thừa đại tràng"]},"actions":["Thiết lập đường truyền, hồi sức dịch và đánh giá huyết động song song với chuẩn bị nội soi","Thực hiện nội soi trong vòng 24 giờ sau khi hồi sức và ổn định ban đầu","Trì hoãn hồi sức và nội soi cho đến khi người bệnh tự hết nôn máu","Truyền hồng cầu lắng vì hemoglobin dưới ngưỡng 7 g/dL, đồng thời đánh giá triệu chứng và bệnh kèm","Cho xuất viện chỉ với thuốc kháng acid vì huyết áp còn đo được"]}}'::jsonb,
