values (
  'noi-tieu-hoa-011',
  '{"schema_version":"1.0.0","case_id":"noi-tieu-hoa-011","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-ugib-acg-2021-8821478c1bdd","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/33929377/","title":"Laine L, Barkun AN, Saltzman JR, et al. ACG Clinical Guideline: Upper Gastrointestinal and Ulcer Bleeding, 2021. https://pubmed.ncbi.nlm.nih.gov/33929377/ . Trích: “red blood cell transfusion at a threshold of 7 g/dL ... endoscopy is suggested within 24 hours after presentation.”","organization":null,"year_version":null,"citation":"Laine L, Barkun AN, Saltzman JR, et al. ACG Clinical Guideline: Upper Gastrointestinal and Ulcer Bleeding, 2021. https://pubmed.ncbi.nlm.nih.gov/33929377/ . Trích: “red blood cell transfusion at a threshold of 7 g/dL ... endoscopy is suggested within 24 hours after presentation.”","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2],"examination_essential_indices":[0,1,2],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"}],"diagnosis_options":{"ydx":[{"text":"Xuất huyết tiêu hóa trên do loét dạ dày-tá tràng","credit":"full"},{"text":"Xuất huyết tiêu hóa dưới do túi thừa đại tràng","credit":"none"},{"text":"Viêm tụy cấp","credit":"none"},{"text":"Tắc ruột cơ học","credit":"none"}]},"action_options":[{"text":"Thiết lập đường truyền, hồi sức dịch và đánh giá huyết động song song với chuẩn bị nội soi","time_minutes":2,"grade":"recommended","rationale":"Ổn định ban đầu trước can thiệp nội soi."},{"text":"Truyền hồng cầu lắng vì hemoglobin dưới ngưỡng 7 g/dL, đồng thời đánh giá triệu chứng và bệnh kèm","time_minutes":3,"grade":"recommended","rationale":"ACG khuyến nghị chiến lược truyền máu hạn chế với ngưỡng 7 g/dL ở UGIB nhập viện."},{"text":"Thực hiện nội soi trong vòng 24 giờ sau khi hồi sức và ổn định ban đầu","time_minutes":3,"grade":"recommended","rationale":"ACG khuyến nghị nội soi trong vòng 24 giờ ở người bệnh UGIB nhập viện hoặc theo dõi tại bệnh viện."},{"text":"Cho xuất viện chỉ với thuốc kháng acid vì huyết áp còn đo được","time_minutes":0,"grade":"waste","rationale":"Bệnh cảnh xuất huyết đang hoạt động và thiếu máu nặng cần điều trị nội trú."},{"text":"Trì hoãn hồi sức và nội soi cho đến khi người bệnh tự hết nôn máu","time_minutes":0,"grade":"harmful","rationale":"Có thể làm chậm kiểm soát xuất huyết và tăng nguy cơ suy tuần hoàn."}],"teaching_explanation":"Xuất huyết tiêu hóa trên cần đánh giá huyết động và hồi sức ngay, đồng thời xác định nguy cơ và nguồn chảy máu. Chiến lược truyền máu hạn chế và nội soi sớm sau hồi sức là các điểm thực hành quan trọng."}'::jsonb,
  'a008c69a65e3451717f57e8d5ac5fe17b1f6aacaa951a5e61a61190c98fb2113'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'noi-tim-mach-007',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-tim-mach-007","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Hồi hộp, mạch không đều ở người tăng huyết áp và đái tháo đường","setting":"giuong","level":"Trung bình","track":"noi","mode":"tay","specialty":null,"demographics":{"age":72,"sex":"nữ","patient_label":"Người bệnh mô phỏng B"},"presentation":{"intro":"Người bệnh nằm giường Nội tim mạch vì hồi hộp từng cơn, mệt và phát hiện nhịp tim không đều.","place":null,"clock":null,"night":false},"vitals":{"hr":132,"sbp":126,"dbp":78,"rr":18,"temperature_c":36.6,"spo2":98},"history":[{"question":"Hồi hộp bắt đầu khi nào và có tự hết không?","response":"Xuất hiện từng cơn trong nhiều tháng, gần đây kéo dài hơn và gây mệt."},{"question":"Có đau ngực, khó thở, ngất hoặc dấu thần kinh khu trú không?","response":"Không ngất, không yếu liệt; đôi lúc hụt hơi khi tim đập nhanh."},{"question":"Có tiền sử tăng huyết áp, đái tháo đường, suy tim hoặc đột quỵ không?","response":"Có tăng huyết áp và đái tháo đường, chưa từng đột quỵ."},{"question":"Có bệnh van tim hoặc thay van cơ học không?","response":"Chưa ghi nhận bệnh van tim nặng hay van cơ học."},{"question":"Đang dùng aspirin hay thuốc chống đông không?","response":"Không dùng thuốc chống đông."}],"examination":[{"group":"K","item":"Bắt mạch và nghe tim","finding":"Mạch hoàn toàn không đều, tần số nhanh; tiếng tim không đều."},{"group":"K","item":"Khám dấu suy tim","finding":"Không ran ẩm phổi, không phù ngoại biên rõ."},{"group":"K","item":"Khám thần kinh khu trú","finding":"Không phát hiện yếu liệt hoặc rối loạn ngôn ngữ."},{"group":"K","item":"Khám tuyến giáp","finding":"Không có bướu giáp hoặc run đầu chi rõ."}],"investigations":[{"name":"Điện tâm đồ 12 chuyển đạo","duration_minutes":10,"result":"Rung nhĩ với đáp ứng thất nhanh."},{"name":"Công thức máu, điện giải, chức năng thận","duration_minutes":10,"result":"Không có thiếu máu nặng hoặc rối loạn điện giải nổi bật."},{"name":"TSH","duration_minutes":10,"result":"Không gợi ý cường giáp."},{"name":"Siêu âm tim","duration_minutes":15,"result":"Không có hẹp van hai lá mức vừa-nặng, không có van tim cơ học."}],"choices":{"diagnosis":{"ydx":["Nhịp nhanh xoang đơn thuần","Ngoại tâm thu thất đơn độc","Rung nhĩ không do hẹp van hai lá mức vừa-nặng hoặc van tim cơ học","Cuồng nhĩ với dẫn truyền cố định"]},"actions":["Không phòng ngừa thuyên tắc chỉ vì rung nhĩ xuất hiện từng cơn rồi tự hết","Dùng aspirin đơn thuần thay cho thuốc chống đông để phòng đột quỵ","Đánh giá nguy cơ thuyên tắc bằng thang điểm lâm sàng đã được thẩm định và cân nhắc kháng đông theo nguy cơ","Ở người bệnh đủ nguy cơ và không có hẹp van hai lá thấp mức vừa-nặng hoặc van cơ học, ưu tiên DOAC hơn warfarin nếu không có chống chỉ định","Kiểm soát tần số hoặc nhịp tùy triệu chứng, huyết động và bệnh tim nền"]}}'::jsonb,
  '66e6eddfc94a65a5a2dbc76a45897f1b676aac156361a1453bb5aa2613eb507b'
)
on conflict (case_id) do update set
  schema_version = excluded.schema_version,
  data_origin = excluded.data_origin,
  review_status = excluded.review_status,
  public_bundle = excluded.public_bundle,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.answer_keys
  (case_id, answer_key, content_sha256)
values (
  'noi-tim-mach-007',
  '{"schema_version":"1.0.0","case_id":"noi-tim-mach-007","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-noi-tim-mach-007-1","resource_type":"other","source":"2023 ACC/AHA/ACCP/HRS Guideline for the Diagnosis and Management of Atrial Fibrillation. https://www.jacc.org/doi/10.1016/j.jacc.2023.08.017 . Trích: “annual thromboembolic risk of ≥2% per year (eg, CHA2DS2-VASc score of ≥2 in men and ≥3 in women), anticoagulation is recommended”.","title":"2023 ACC/AHA/ACCP/HRS Guideline for the Diagnosis and Management of Atrial Fibrillation. https://www.jacc.org/doi/10.1016/j.jacc.2023.08.017 . Trích: “annual thromboembolic risk of ≥2% per year (eg, CHA2DS2-VASc score of ≥2 in men and ≥3 in women), anticoagulation is recommended”.","organization":null,"year_version":null,"citation":"2023 ACC/AHA/ACCP/HRS Guideline for the Diagnosis and Management of Atrial Fibrillation. https://www.jacc.org/doi/10.1016/j.jacc.2023.08.017 . Trích: “annual thromboembolic risk of ≥2% per year (eg, CHA2DS2-VASc score of ≥2 in men and ≥3 in women), anticoagulation is recommended”.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3],"examination_essential_indices":[0,1,2],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"}],"diagnosis_options":{"ydx":[{"text":"Rung nhĩ không do hẹp van hai lá mức vừa-nặng hoặc van tim cơ học","credit":"full"},{"text":"Nhịp nhanh xoang đơn thuần","credit":"none"},{"text":"Cuồng nhĩ với dẫn truyền cố định","credit":"none"},{"text":"Ngoại tâm thu thất đơn độc","credit":"none"}]},"action_options":[{"text":"Đánh giá nguy cơ thuyên tắc bằng thang điểm lâm sàng đã được thẩm định và cân nhắc kháng đông theo nguy cơ","time_minutes":3,"grade":"recommended","rationale":"Khuyến cáo AF yêu cầu đánh giá nguy cơ thuyên tắc hằng năm."},{"text":"Ở người bệnh đủ nguy cơ và không có hẹp van hai lá thấp mức vừa-nặng hoặc van cơ học, ưu tiên DOAC hơn warfarin nếu không có chống chỉ định","time_minutes":3,"grade":"recommended","rationale":"Guideline ưu tiên DOAC ở AF không thuộc nhóm van tim cần warfarin."},{"text":"Kiểm soát tần số hoặc nhịp tùy triệu chứng, huyết động và bệnh tim nền","time_minutes":2,"grade":"recommended","rationale":"Mục tiêu điều trị triệu chứng được cá thể hóa."},{"text":"Dùng aspirin đơn thuần thay cho thuốc chống đông để phòng đột quỵ","time_minutes":0,"grade":"waste","rationale":"Aspirin không được khuyến nghị như phương án thay thế kháng đông ở người đủ chỉ định."},{"text":"Không phòng ngừa thuyên tắc chỉ vì rung nhĩ xuất hiện từng cơn rồi tự hết","time_minutes":0,"grade":"harmful","rationale":"Nguy cơ đột quỵ được quyết định theo nguy cơ thuyên tắc, không chỉ dựa vào kiểu rung nhĩ."}],"teaching_explanation":"Ở rung nhĩ, quyết định phòng ngừa đột quỵ dựa vào nguy cơ thuyên tắc và nguy cơ chảy máu, không chỉ dựa vào rung nhĩ kịch phát hay dai dẳng. Khi đủ chỉ định và không có hẹp van hai lá thấp mức vừa-nặng hoặc van cơ học, DOAC thường được ưu tiên."}'::jsonb,
  '101a55c39c921c56a8f6267e5a16448c2bd91b205919960fd10654f37e6db91a'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'noi-ho-hap-006',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-ho-hap-006","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Khó thở tăng, khạc đờm mủ ở người COPD","setting":"giuong","level":"Trung bình","track":"noi","mode":"tay","specialty":null,"demographics":{"age":67,"sex":"nam","patient_label":"Người bệnh mô phỏng C"},"presentation":{"intro":"Người bệnh nằm giường Nội hô hấp vì khó thở tăng, khò khè và đờm chuyển vàng.","place":null,"clock":null,"night":false},"vitals":{"hr":104,"sbp":132,"dbp":76,"rr":30,"temperature_c":37.8,"spo2":84},"history":[{"question":"Khó thở tăng từ khi nào và so với mức nền thế nào?","response":"Khó thở tăng rõ trong vài ngày, đi lại trong phòng cũng hụt hơi."},{"question":"Lượng và màu đờm có thay đổi không?","response":"Đờm nhiều hơn và chuyển vàng đục."},{"question":"Có sốt, đau ngực kiểu màng phổi hoặc ho ra máu không?","response":"Sốt nhẹ, không đau ngực kiểu màng phổi, không ho ra máu."},{"question":"Đang dùng thuốc hít gì và kỹ thuật dùng thuốc ra sao?","response":"Có thuốc giãn phế quản nhưng dùng không đều."},{"question":"Có tiền sử đặt nội khí quản hoặc đợt cấp phải thở máy không?","response":"Chưa từng đặt nội khí quản."}],"examination":[{"group":"K","item":"Quan sát hô hấp","finding":"Thở nhanh, sử dụng cơ hô hấp phụ mức độ vừa."},{"group":"K","item":"Nghe phổi","finding":"Rì rào phế nang giảm, ran rít và ran ngáy hai bên."},{"group":"K","item":"Đánh giá tri giác","finding":"Tỉnh, tiếp xúc được, chưa có lú lẫn."},{"group":"K","item":"Khám tim và phù","finding":"Không phù ngoại biên rõ, tim nhanh đều."}],"investigations":[{"name":"Khí máu động mạch","duration_minutes":15,"result":"pH 7,31, PaCO2 58 mmHg, có toan hô hấp tăng CO2."},{"name":"X-quang ngực","duration_minutes":10,"result":"Không thấy tràn khí màng phổi hoặc đông đặc thùy rõ."},{"name":"Công thức máu và CRP","duration_minutes":10,"result":"Có phản ứng viêm mức vừa."},{"name":"Điện tâm đồ","duration_minutes":10,"result":"Nhịp xoang nhanh, không có thiếu máu cơ tim cấp rõ."}],"choices":{"diagnosis":{"ydx":["Cơn hen đơn thuần ở người chưa có COPD","Tràn khí màng phổi áp lực","Phù phổi cấp do tim","Đợt cấp COPD kèm suy hô hấp tăng CO2"]},"actions":["Cân nhắc hỗ trợ thông khí không xâm nhập khi có suy hô hấp tăng CO2 và toan hô hấp phù hợp","Cho oxy không kiểm soát nhằm đưa bão hòa lên tối đa bất kể nguy cơ giữ CO2","Dùng methylxanthine tĩnh mạch thường quy cho mọi đợt cấp COPD","Chuẩn độ oxy để đạt SpO2 mục tiêu 88–92% và đánh giá lại khí máu theo diễn biến","Dùng thuốc giãn phế quản tác dụng ngắn, có thể phối hợp kháng cholinergic tác dụng ngắn","Dùng corticosteroid toàn thân tương đương prednisone 40 mg mỗi ngày trong 5 ngày nếu không có chống chỉ định"]}}'::jsonb,
  'e8d8fc5761ce3d72af8bd83e6602c2b9f8e0d6932a3e79854394ba6018ee5ded'
)
on conflict (case_id) do update set
  schema_version = excluded.schema_version,
  data_origin = excluded.data_origin,
  review_status = excluded.review_status,
  public_bundle = excluded.public_bundle,
