insert into can_lam_sang_private.answer_keys
  (case_id, answer_key, content_sha256)
values (
  'noi-ho-hap-006',
  '{"schema_version":"1.0.0","case_id":"noi-ho-hap-006","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-gold-2025-b5afb3bf4d46","resource_type":"guideline","source":"https://goldcopd.org/2025-gold-report/","title":"Global Initiative for Chronic Obstructive Lung Disease, GOLD Report 2026. https://goldcopd.org/wp-content/uploads/2026/01/GOLD-REPORT-2026-v1.3-8Dec2025_WMV2.pdf . Trích: “A dose of 40 mg prednisone-equivalent per day for 5 days is recommended”; “target saturation of 88-92%”.","organization":null,"year_version":null,"citation":"Global Initiative for Chronic Obstructive Lung Disease, GOLD Report 2026. https://goldcopd.org/wp-content/uploads/2026/01/GOLD-REPORT-2026-v1.3-8Dec2025_WMV2.pdf . Trích: “A dose of 40 mg prednisone-equivalent per day for 5 days is recommended”; “target saturation of 88-92%”.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2],"examination_essential_indices":[0,1,2],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"neutral"},{"index":3,"role":"neutral"}],"diagnosis_options":{"ydx":[{"text":"Đợt cấp COPD kèm suy hô hấp tăng CO2","credit":"full"},{"text":"Cơn hen đơn thuần ở người chưa có COPD","credit":"none"},{"text":"Phù phổi cấp do tim","credit":"none"},{"text":"Tràn khí màng phổi áp lực","credit":"none"}]},"action_options":[{"text":"Chuẩn độ oxy để đạt SpO2 mục tiêu 88–92% và đánh giá lại khí máu theo diễn biến","time_minutes":3,"grade":"recommended","rationale":"GOLD khuyến cáo oxy có kiểm soát trong đợt cấp COPD."},{"text":"Dùng corticosteroid toàn thân tương đương prednisone 40 mg mỗi ngày trong 5 ngày nếu không có chống chỉ định","time_minutes":3,"grade":"recommended","rationale":"GOLD khuyến cáo liều và thời gian này trong đợt cấp COPD."},{"text":"Dùng thuốc giãn phế quản tác dụng ngắn, có thể phối hợp kháng cholinergic tác dụng ngắn","time_minutes":2,"grade":"recommended","rationale":"Là điều trị giãn phế quản ban đầu trong đợt cấp."},{"text":"Cân nhắc hỗ trợ thông khí không xâm nhập khi có suy hô hấp tăng CO2 và toan hô hấp phù hợp","time_minutes":3,"grade":"recommended","rationale":"NIV là biện pháp hỗ trợ quan trọng ở đợt cấp có suy hô hấp tăng CO2."},{"text":"Dùng methylxanthine tĩnh mạch thường quy cho mọi đợt cấp COPD","time_minutes":0,"grade":"waste","rationale":"GOLD không khuyến cáo methylxanthine tĩnh mạch do tác dụng phụ."},{"text":"Cho oxy không kiểm soát nhằm đưa bão hòa lên tối đa bất kể nguy cơ giữ CO2","time_minutes":0,"grade":"harmful","rationale":"Có thể làm nặng tăng CO2; cần oxy chuẩn độ theo mục tiêu."}],"teaching_explanation":"Đợt cấp COPD cần đánh giá mức độ suy hô hấp, nguyên nhân khởi phát và bệnh đồng mắc. Oxy phải được chuẩn độ, corticosteroid toàn thân dùng ngắn ngày và NIV được cân nhắc khi có suy hô hấp tăng CO2 kèm toan."}'::jsonb,
  'df9b29f5bc130dde1032e9d8c7e3c8ea3db78595ea9daa33ee6b29e5631fe5de'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
