values (
  'noi-nhiem-003',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-nhiem-003","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Sốt cao, tụt huyết áp và thiểu niệu do nhiễm trùng","setting":"giuong","level":"Khó","track":"noi","mode":"tay","specialty":null,"demographics":{"age":59,"sex":"nam","patient_label":"Người bệnh mô phỏng D"},"presentation":{"intro":"Người bệnh nằm giường Nội nhiễm vì sốt rét run, lơ mơ nhẹ, huyết áp tụt và tiểu ít trên nền nhiễm trùng đường tiết niệu.","place":null,"clock":null,"night":false},"vitals":{"hr":118,"sbp":82,"dbp":48,"rr":26,"temperature_c":39.2,"spo2":95},"history":[{"question":"Sốt và rét run bắt đầu từ khi nào?","response":"Sốt cao, rét run và mệt tăng nhanh trong ngày nhập viện."},{"question":"Có tiểu buốt, tiểu gắt hoặc đau hông lưng không?","response":"Có tiểu buốt, tiểu gắt và đau hông lưng trước khi sốt tăng."},{"question":"Có lú lẫn, chóng mặt hoặc tiểu ít không?","response":"Có lơ mơ nhẹ, chóng mặt và lượng nước tiểu giảm."},{"question":"Đã dùng kháng sinh gần đây hoặc có tiền sử vi khuẩn kháng thuốc không?","response":"Chưa dùng kháng sinh trong đợt này, chưa biết tiền sử vi khuẩn đa kháng."},{"question":"Có bệnh tim, thận hoặc xơ gan không?","response":"Chưa ghi nhận suy tim, suy thận mạn hoặc xơ gan."}],"examination":[{"group":"K","item":"Đánh giá tưới máu ngoại vi","finding":"Chi lạnh, thời gian làm đầy mao mạch kéo dài."},{"group":"K","item":"Đánh giá tri giác","finding":"Lơ mơ nhẹ nhưng còn đáp ứng khi gọi."},{"group":"K","item":"Khám hông lưng","finding":"Đau vùng hông lưng gợi nguồn nhiễm tiết niệu."},{"group":"K","item":"Khám phổi","finding":"Không có ran khu trú rõ."}],"investigations":[{"name":"Lactate máu","duration_minutes":10,"result":"Lactate tăng, phù hợp giảm tưới máu mô."},{"name":"Cấy máu và cấy nước tiểu","duration_minutes":15,"result":"Đã lấy mẫu trước kháng sinh nếu không làm chậm điều trị."},{"name":"Công thức máu, creatinin, bilirubin, đông máu","duration_minutes":10,"result":"Có rối loạn chức năng cơ quan mức độ cần theo dõi sát."},{"name":"Siêu âm hệ tiết niệu","duration_minutes":15,"result":"Đánh giá tắc nghẽn và nguồn nhiễm cần kiểm soát."}],"choices":{"diagnosis":{"ydx":["Sốc nhiễm khuẩn do nhiễm trùng đường tiết niệu","Sốc tim","Sốc phản vệ","Sốc giảm thể tích đơn thuần"]},"actions":["Nếu vẫn cần vận mạch, chỉnh vận mạch theo mục tiêu MAP ban đầu 65 mmHg","Lấy cấy máu sớm nếu không làm chậm điều trị và khởi kháng sinh phù hợp ngay khi nghi sốc nhiễm khuẩn","Trì hoãn kháng sinh cho đến khi có kết quả cấy và kháng sinh đồ","Dùng qSOFA đơn độc để loại trừ sepsis khi điểm thấp","Bắt đầu hồi sức ngay và dùng dịch tinh thể với lượng ban đầu ít nhất 30 mL/kg trong 3 giờ đầu ở người có giảm tưới máu do sepsis hoặc sốc nhiễm khuẩn, sau đó đánh giá lại thường xuyên"]}}'::jsonb,
  '51cf2dc40d7ceb514c4111201dfe651ce99c2035eb8aab3992599fc83ed1ad3f'
)
