insert into can_lam_sang_private.answer_keys
  (case_id, answer_key, content_sha256)
values (
  'noi-nhiem-003',
  '{"schema_version":"1.0.0","case_id":"noi-nhiem-003","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-sepsis-ssc-2021-ee3c0fd08779","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/34605781/","title":"Society of Critical Care Medicine, Surviving Sepsis Campaign Adult Guidelines. https://sccm.org/survivingsepsiscampaign/guidelines-and-resources/surviving-sepsis-campaign-adult-guidelines . Trích: “at least 30 mL/kg of IV crystalloid in the first 3 hr”; “initial MAP target of 65 mm Hg”.","organization":null,"year_version":null,"citation":"Society of Critical Care Medicine, Surviving Sepsis Campaign Adult Guidelines. https://sccm.org/survivingsepsiscampaign/guidelines-and-resources/surviving-sepsis-campaign-adult-guidelines . Trích: “at least 30 mL/kg of IV crystalloid in the first 3 hr”; “initial MAP target of 65 mm Hg”.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2],"examination_essential_indices":[0,1,2],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"}],"diagnosis_options":{"ydx":[{"text":"Sốc nhiễm khuẩn do nhiễm trùng đường tiết niệu","credit":"full"},{"text":"Sốc phản vệ","credit":"none"},{"text":"Sốc tim","credit":"none"},{"text":"Sốc giảm thể tích đơn thuần","credit":"none"}]},"action_options":[{"text":"Bắt đầu hồi sức ngay và dùng dịch tinh thể với lượng ban đầu ít nhất 30 mL/kg trong 3 giờ đầu ở người có giảm tưới máu do sepsis hoặc sốc nhiễm khuẩn, sau đó đánh giá lại thường xuyên","time_minutes":3,"grade":"recommended","rationale":"SSC khuyến cáo hồi sức dịch tinh thể sớm và tái đánh giá liên tục."},{"text":"Nếu vẫn cần vận mạch, chỉnh vận mạch theo mục tiêu MAP ban đầu 65 mmHg","time_minutes":3,"grade":"recommended","rationale":"SSC khuyến cáo mục tiêu MAP ban đầu 65 mmHg ở sốc nhiễm khuẩn cần vận mạch."},{"text":"Lấy cấy máu sớm nếu không làm chậm điều trị và khởi kháng sinh phù hợp ngay khi nghi sốc nhiễm khuẩn","time_minutes":3,"grade":"recommended","rationale":"Sepsis là cấp cứu; điều trị kháng sinh không nên chờ kết quả cấy."},{"text":"Dùng qSOFA đơn độc để loại trừ sepsis khi điểm thấp","time_minutes":0,"grade":"waste","rationale":"Sepsis là chẩn đoán lâm sàng và không nên bị loại trừ bằng một công cụ đơn lẻ."},{"text":"Trì hoãn kháng sinh cho đến khi có kết quả cấy và kháng sinh đồ","time_minutes":0,"grade":"harmful","rationale":"Làm chậm điều trị nhiễm trùng trong sốc nhiễm khuẩn."}],"teaching_explanation":"Sốc nhiễm khuẩn là cấp cứu cần hồi sức và điều trị nguyên nhân đồng thời. Dịch tinh thể ban đầu, đánh giá lại tưới máu và vận mạch khi cần phải được thực hiện song song với kháng sinh và kiểm soát nguồn nhiễm."}'::jsonb,
  '4c1d7c1c129e30dfb6e9acd526836f412f6df9ec271b52c0076167899dac1fca'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'noi-noi-tiet-004',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-noi-tiet-004","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Nôn, đau bụng và thở sâu ở người đái tháo đường típ một","setting":"giuong","level":"Khó","track":"noi","mode":"tay","specialty":null,"demographics":{"age":29,"sex":"nữ","patient_label":"Người bệnh mô phỏng E"},"presentation":{"intro":"Người bệnh nằm giường Nội tiết vì nôn, đau bụng, khát nhiều, tiểu nhiều và thở sâu sau khi bỏ nhiều liều insulin.","place":null,"clock":null,"night":false},"vitals":{"hr":112,"sbp":104,"dbp":66,"rr":28,"temperature_c":37.1,"spo2":98},"history":[{"question":"Có bỏ hoặc giảm insulin gần đây không?","response":"Bỏ nhiều liều insulin trong những ngày trước nhập viện vì ăn uống kém."},{"question":"Có khát nhiều, tiểu nhiều và sụt cân không?","response":"Khát nhiều, tiểu nhiều, mệt và ăn kém."},{"question":"Có nôn, đau bụng hoặc thay đổi tri giác không?","response":"Nôn nhiều lần, đau bụng lan tỏa, còn tỉnh nhưng mệt lả."},{"question":"Có sốt, ho, tiểu buốt hoặc dấu nhiễm trùng không?","response":"Không sốt rõ; cần tiếp tục tìm yếu tố khởi phát."},{"question":"Có dùng thuốc ức chế SGLT2 không?","response":"Không dùng."}],"examination":[{"group":"K","item":"Đánh giá kiểu thở","finding":"Thở sâu và nhanh kiểu Kussmaul."},{"group":"K","item":"Đánh giá tình trạng mất nước","finding":"Niêm mạc khô, khát, mạch nhanh."},{"group":"K","item":"Khám tri giác","finding":"Tỉnh, trả lời đúng nhưng mệt."},{"group":"K","item":"Khám bụng","finding":"Đau nhẹ lan tỏa, không phản ứng phúc mạc."}],"investigations":[{"name":"Glucose máu","duration_minutes":10,"result":"Glucose 420 mg/dL."},{"name":"Khí máu tĩnh mạch hoặc động mạch","duration_minutes":10,"result":"pH 7,18 và bicarbonate 10 mmol/L."},{"name":"Beta-hydroxybutyrate máu","duration_minutes":10,"result":"Tăng rõ, phù hợp nhiễm ceton."},{"name":"Điện giải và chức năng thận","duration_minutes":10,"result":"Cần theo dõi kali sát trong quá trình điều trị."}],"choices":{"diagnosis":{"ydx":["Viêm dạ dày-ruột cấp đơn thuần","Nhiễm toan ceton do đái tháo đường","Tăng đường huyết không ceton đơn thuần","Hạ đường huyết"]},"actions":["Khởi truyền dung dịch đẳng trương hoặc crystalloid cân bằng với tốc độ 500–1000 mL/giờ trong 2–4 giờ đầu nếu không có suy tim hoặc suy thận hạn chế bù dịch","Theo dõi glucose, điện giải, tình trạng dịch và ceton để điều chỉnh điều trị cho tới khi nhiễm toan ceton giải quyết","Chỉ truyền dịch mà không dùng insulin dù đã xác định DKA","Ngừng insulin ngay khi glucose bắt đầu giảm mặc dù nhiễm toan ceton chưa giải quyết","Sau đánh giá kali và tình trạng phù hợp, dùng insulin regular truyền tĩnh mạch liên tục 0,1 đơn vị/kg/giờ"]}}'::jsonb,
  'd397e80e5b97501be7785460e23b21641c7997a8b2f1e17417f002ef9e2c63a9'
)
on conflict (case_id) do update set
