insert into can_lam_sang_private.answer_keys
  (case_id, answer_key, content_sha256)
values (
  'noi-noi-tiet-004',
  '{"schema_version":"1.0.0","case_id":"noi-noi-tiet-004","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-dka-ada-2024-a511779b1c4f","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/39052901/","title":"Umpierrez GE, Davis GM, ElSayed NA, et al. Hyperglycemic Crises in Adults With Diabetes: A Consensus Report, 2024. https://diabetesjournals.org/care/article/47/8/1257/156808/Hyperglycemic-Crises-in-Adults-With-Diabetes-A . Trích: “500–1,000 mL/h during the first 2–4 h”; “fixed-rate intravenous insulin infusion started at 0.1 units/kg/h”.","organization":null,"year_version":null,"citation":"Umpierrez GE, Davis GM, ElSayed NA, et al. Hyperglycemic Crises in Adults With Diabetes: A Consensus Report, 2024. https://diabetesjournals.org/care/article/47/8/1257/156808/Hyperglycemic-Crises-in-Adults-With-Diabetes-A . Trích: “500–1,000 mL/h during the first 2–4 h”; “fixed-rate intravenous insulin infusion started at 0.1 units/kg/h”.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2],"examination_essential_indices":[0,1,2],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"}],"diagnosis_options":{"ydx":[{"text":"Nhiễm toan ceton do đái tháo đường","credit":"full"},{"text":"Hạ đường huyết","credit":"none"},{"text":"Tăng đường huyết không ceton đơn thuần","credit":"none"},{"text":"Viêm dạ dày-ruột cấp đơn thuần","credit":"none"}]},"action_options":[{"text":"Khởi truyền dung dịch đẳng trương hoặc crystalloid cân bằng với tốc độ 500–1000 mL/giờ trong 2–4 giờ đầu nếu không có suy tim hoặc suy thận hạn chế bù dịch","time_minutes":3,"grade":"recommended","rationale":"Đồng thuận 2024 khuyến cáo tốc độ dịch ban đầu này ở người lớn DKA/HHS không có hạn chế tim-thận."},{"text":"Sau đánh giá kali và tình trạng phù hợp, dùng insulin regular truyền tĩnh mạch liên tục 0,1 đơn vị/kg/giờ","time_minutes":3,"grade":"recommended","rationale":"Insulin truyền tĩnh mạch tốc độ cố định là nền tảng điều trị DKA."},{"text":"Theo dõi glucose, điện giải, tình trạng dịch và ceton để điều chỉnh điều trị cho tới khi nhiễm toan ceton giải quyết","time_minutes":3,"grade":"recommended","rationale":"Điều trị cần theo dõi chuyển hóa liên tục và không chỉ dựa vào glucose."},{"text":"Chỉ truyền dịch mà không dùng insulin dù đã xác định DKA","time_minutes":0,"grade":"waste","rationale":"Không giải quyết được tình trạng thiếu insulin và tạo ceton."},{"text":"Ngừng insulin ngay khi glucose bắt đầu giảm mặc dù nhiễm toan ceton chưa giải quyết","time_minutes":0,"grade":"harmful","rationale":"Có nguy cơ tái tăng ceton và kéo dài DKA."}],"teaching_explanation":"DKA là cấp cứu chuyển hóa do thiếu insulin, cần bù dịch, insulin và theo dõi điện giải đồng thời. Mục tiêu không chỉ là hạ glucose mà phải giải quyết nhiễm ceton và toan chuyển hóa."}'::jsonb,
  '67f34a3e44e5978ef23805f206c5ba7223b663d4b977d081f2010b70334d1fcc'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
