values (
  'noi-tieu-hoa-012',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-tieu-hoa-012","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Xơ gan có cổ trướng, sốt và đau bụng","setting":"giuong","level":"Trung bình","track":"noi","mode":"tay","specialty":null,"demographics":{"age":58,"sex":"nam","patient_label":"Người bệnh mô phỏng A"},"presentation":{"intro":"Người bệnh xơ gan có cổ trướng nhập khoa Nội tiêu hóa vì sốt, đau bụng âm ỉ và mệt tăng.","place":null,"clock":null,"night":false},"vitals":{"hr":102,"sbp":104,"dbp":66,"rr":20,"temperature_c":38.2,"spo2":97},"history":[{"question":"Đau bụng xuất hiện như thế nào?","response":"Đau âm ỉ lan tỏa, kèm bụng căng hơn và mệt nhiều."},{"question":"Có sốt hoặc rét run không?","response":"Có sốt và cảm giác rét nhưng không rét run dữ dội."},{"question":"Có lú lẫn hoặc ngủ gà hơn bình thường không?","response":"Người nhà thấy chậm chạp hơn nhưng vẫn trả lời đúng."},{"question":"Có nôn ra máu hoặc đi cầu phân đen không?","response":"Không ghi nhận xuất huyết tiêu hóa hiện tại."},{"question":"Có từng nhiễm trùng dịch cổ trướng trước đây không?","response":"Chưa ghi nhận đợt tương tự."}],"examination":[{"group":"K","item":"Khám bụng","finding":"Bụng chướng, có dấu cổ trướng, ấn đau nhẹ lan tỏa nhưng không phản ứng thành bụng rõ."},{"group":"K","item":"Đánh giá tri giác","finding":"Tỉnh, tiếp xúc chậm nhẹ, không có dấu thần kinh khu trú."},{"group":"K","item":"Khám dấu bệnh gan mạn","finding":"Có vàng da nhẹ và phù hai chi dưới."},{"group":"K","item":"Khám tim phổi","finding":"Tim đều, phổi chưa ghi nhận ran ẩm lan tỏa."}],"investigations":[{"name":"Chọc dò dịch cổ trướng làm tế bào và công thức bạch cầu","duration_minutes":15,"result":"Bạch cầu đa nhân trung tính dịch cổ trướng 620 tế bào/mm3."},{"name":"Cấy dịch cổ trướng bằng chai cấy máu tại giường","duration_minutes":15,"result":"Đã lấy mẫu trước khi khởi kháng sinh nếu không làm chậm điều trị."},{"name":"Công thức máu, chức năng gan thận và điện giải","duration_minutes":10,"result":"Có phản ứng viêm và cần theo dõi chức năng thận."},{"name":"Siêu âm bụng","duration_minutes":10,"result":"Xơ gan, nhiều dịch cổ trướng, chưa thấy ổ nhiễm khuẩn ngoại khoa rõ."}],"choices":{"diagnosis":{"ydx":["Nhiễm trùng dịch cổ trướng tự phát trên nền xơ gan","Viêm tụy cấp","Viêm ruột thừa cấp","Tắc ruột cơ học"]},"actions":["Trì hoãn chọc dò dịch cổ trướng và kháng sinh cho đến khi có biểu hiện viêm phúc mạc rõ","Khởi kháng sinh kinh nghiệm ngay khi chẩn đoán hoặc nghi ngờ cao, lựa chọn theo nguồn nhiễm và mô hình kháng thuốc tại cơ sở","Chọc dò dịch cổ trướng không trì hoãn để đếm bạch cầu đa nhân trung tính và cấy dịch","Theo dõi chức năng thận, huyết động và biến chứng não gan trong quá trình điều trị","Chỉ tăng liều lợi tiểu để giảm căng bụng mà không khảo sát nguyên nhân sốt và đau bụng"]}}'::jsonb,
  'daa7d4fde9e34087ca55e1a53e5bdd60e018909bc85473fc1aedd657ee8bcf06'
)
