insert into can_lam_sang_private.answer_keys
  (case_id, answer_key, content_sha256)
values (
  'noi-tieu-hoa-012',
  '{"schema_version":"1.0.0","case_id":"noi-tieu-hoa-012","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-noi-tieu-hoa-012-1","resource_type":"other","source":"British Society of Gastroenterology/BASL. Guidelines on the management of ascites in cirrhosis, Gut 2021. https://gut.bmj.com/content/70/1/9 . Trích: “Ascitic neutrophil >250/mm3 count remains the gold standard for the diagnosis of SBP.”","title":"British Society of Gastroenterology/BASL. Guidelines on the management of ascites in cirrhosis, Gut 2021. https://gut.bmj.com/content/70/1/9 . Trích: “Ascitic neutrophil >250/mm3 count remains the gold standard for the diagnosis of SBP.”","organization":null,"year_version":null,"citation":"British Society of Gastroenterology/BASL. Guidelines on the management of ascites in cirrhosis, Gut 2021. https://gut.bmj.com/content/70/1/9 . Trích: “Ascitic neutrophil >250/mm3 count remains the gold standard for the diagnosis of SBP.”","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2],"examination_essential_indices":[0,1,2],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"neutral"}],"diagnosis_options":{"ydx":[{"text":"Nhiễm trùng dịch cổ trướng tự phát trên nền xơ gan","credit":"full"},{"text":"Viêm tụy cấp","credit":"none"},{"text":"Viêm ruột thừa cấp","credit":"none"},{"text":"Tắc ruột cơ học","credit":"none"}]},"action_options":[{"text":"Chọc dò dịch cổ trướng không trì hoãn để đếm bạch cầu đa nhân trung tính và cấy dịch","time_minutes":3,"grade":"critical","rationale":"Chẩn đoán sớm SBP ở người xơ gan có cổ trướng nhập viện."},{"text":"Khởi kháng sinh kinh nghiệm ngay khi chẩn đoán hoặc nghi ngờ cao, lựa chọn theo nguồn nhiễm và mô hình kháng thuốc tại cơ sở","time_minutes":3,"grade":"critical","rationale":"Không chờ cấy nếu bệnh cảnh phù hợp."},{"text":"Theo dõi chức năng thận, huyết động và biến chứng não gan trong quá trình điều trị","time_minutes":2,"grade":"recommended","rationale":"SBP có thể thúc đẩy suy thận và mất bù gan."},{"text":"Chỉ tăng liều lợi tiểu để giảm căng bụng mà không khảo sát nguyên nhân sốt và đau bụng","time_minutes":0,"grade":"waste","rationale":"Không xử trí được nhiễm trùng và có thể làm chậm chẩn đoán."},{"text":"Trì hoãn chọc dò dịch cổ trướng và kháng sinh cho đến khi có biểu hiện viêm phúc mạc rõ","time_minutes":0,"grade":"harmful","rationale":"Có thể làm chậm điều trị một nhiễm trùng có nguy cơ tử vong."}],"teaching_explanation":"Ở người xơ gan có cổ trướng nhập viện vì sốt, đau bụng, rối loạn tri giác hoặc suy chức năng thận, cần nghĩ đến nhiễm trùng dịch cổ trướng và chọc dò sớm. Chẩn đoán dựa chủ yếu vào số lượng bạch cầu đa nhân trung tính trong dịch cổ trướng, không phụ thuộc việc cấy có dương tính hay không."}'::jsonb,
  '46b01321c96f14f6d96ff08c65eea60ba35b83ef435eec0c843535bf3219a763'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'noi-than-005',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-than-005","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Ca bệnh noi-than-005","setting":"giuong","level":"Khó","track":"noi","mode":"tay","specialty":null,"demographics":{"age":66,"sex":"nam","patient_label":"Người bệnh mô phỏng B"},"presentation":{"intro":"Người bệnh bệnh thận mạn nhập khoa Nội vì yếu cơ, hồi hộp và phát hiện tăng kali máu nặng.","place":null,"clock":null,"night":false},"vitals":{"hr":54,"sbp":108,"dbp":64,"rr":18,"temperature_c":36.6,"spo2":98},"history":[{"question":"Có yếu cơ, hồi hộp, choáng hoặc ngất không?","response":"Yếu hai chân, hồi hộp và choáng nhẹ, chưa ngất."},{"question":"Lượng nước tiểu gần đây thay đổi không?","response":"Tiểu ít hơn bình thường."},{"question":"Có dùng thuốc làm tăng kali như thuốc ức chế hệ renin-angiotensin hoặc thuốc giữ kali không?","response":"Có dùng thuốc điều trị tăng huyết áp và suy tim, cần rà soát toàn bộ đơn thuốc."},{"question":"Có tiêu chảy, nôn hoặc mất nước không?","response":"Không tiêu chảy, ăn uống kém."},{"question":"Có từng phải lọc máu không?","response":"Chưa từng lọc máu."}],"examination":[{"group":"K","item":"Đánh giá mạch và huyết động","finding":"Mạch chậm, huyết động hiện còn duy trì."},{"group":"K","item":"Khám sức cơ","finding":"Yếu cơ hai chi dưới nhưng không có dấu thần kinh khu trú."},{"group":"K","item":"Đánh giá tình trạng dịch","finding":"Không phù phổi cấp, có dấu giảm bài niệu."},{"group":"K","item":"Khám tim phổi","finding":"Tim chậm, phổi chưa có ran ẩm lan tỏa."}],"investigations":[{"name":"Điện giải máu kiểm tra lại bằng mẫu phù hợp","duration_minutes":10,"result":"Kali 6,8 mmol/L."},{"name":"Điện tâm đồ","duration_minutes":10,"result":"Sóng T cao nhọn và thay đổi dẫn truyền phù hợp tăng kali máu."},{"name":"Khí máu và bicarbonate","duration_minutes":10,"result":"Đánh giá toan kiềm và yếu tố thúc đẩy tăng kali."},{"name":"Creatinin và chức năng thận","duration_minutes":10,"result":"Suy giảm chức năng thận so với nền."}],"choices":{"diagnosis":{"ydx":["Hạ kali máu","Nhịp chậm xoang sinh lý","Hạ calci máu đơn thuần","Tăng kali máu nặng có biến đổi điện tâm đồ"]},"actions":["Bảo vệ tim bằng calcium gluconate 10% 30 mL truyền tĩnh mạch trong 10 phút khi có dấu điện tâm đồ của tăng kali máu","Trì hoãn calcium tĩnh mạch cho đến khi kali giảm sau insulin-glucose","Chỉ ngừng thuốc nghi gây tăng kali rồi chờ xét nghiệm lại mà không điều trị cấp cứu","Chuyển kali vào nội bào bằng 10 đơn vị insulin hòa tan cùng 25 g glucose truyền tĩnh mạch","Theo dõi liên tục điện tâm đồ, glucose máu và kali sau điều trị; đồng thời loại bỏ yếu tố gây tăng kali"]}}'::jsonb,
  'c1eef4cf5d2b41e610b62e0c1057530f7189ad7fd19266722a291146431fd3ba'
)
on conflict (case_id) do update set
  schema_version = excluded.schema_version,
  data_origin = excluded.data_origin,
  review_status = excluded.review_status,
  public_bundle = excluded.public_bundle,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.answer_keys
  (case_id, answer_key, content_sha256)
values (
  'noi-than-005',
  '{"schema_version":"1.0.0","case_id":"noi-than-005","server_only":true,"title_reveal":"Tăng kali máu nặng có biến đổi điện tâm đồ","resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-ukka-hyperkalaemia-94982ae0fdbd","resource_type":"guideline","source":"https://ukkidney.org/guidelines/joint-guidelines/treatment-of-acute-hyperkalaemia-in-adults","title":"UK Kidney Association. Clinical Practice Guideline: Management of Hyperkalaemia in Adults, 2023. https://www.ukkidney.org/sites/default/files/FINAL%20VERSION%20-%20UKKA%20CLINICAL%20PRACTICE%20GUIDELINE%20-%20MANAGEMENT%20OF%20HYPERKALAEMIA%20IN%20ADULTS%20-%20191223.pdf . Trích: “30ml 10% Calcium Gluconate over 10 minutes”; “10 units soluble insulin in 25g glucose”; “K+ ≥ 6.5 mmol/l”.","organization":null,"year_version":null,"citation":"UK Kidney Association. Clinical Practice Guideline: Management of Hyperkalaemia in Adults, 2023. https://www.ukkidney.org/sites/default/files/FINAL%20VERSION%20-%20UKKA%20CLINICAL%20PRACTICE%20GUIDELINE%20-%20MANAGEMENT%20OF%20HYPERKALAEMIA%20IN%20ADULTS%20-%20191223.pdf . Trích: “30ml 10% Calcium Gluconate over 10 minutes”; “10 units soluble insulin in 25g glucose”; “K+ ≥ 6.5 mmol/l”.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2],"examination_essential_indices":[0,1,2],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"}],"diagnosis_options":{"ydx":[{"text":"Tăng kali máu nặng có biến đổi điện tâm đồ","credit":"full"},{"text":"Hạ kali máu","credit":"none"},{"text":"Hạ calci máu đơn thuần","credit":"none"},{"text":"Nhịp chậm xoang sinh lý","credit":"none"}]},"action_options":[{"text":"Bảo vệ tim bằng calcium gluconate 10% 30 mL truyền tĩnh mạch trong 10 phút khi có dấu điện tâm đồ của tăng kali máu","time_minutes":3,"grade":"critical","rationale":"UKKA khuyến cáo calcium tĩnh mạch khi có biến đổi điện tâm đồ."},{"text":"Chuyển kali vào nội bào bằng 10 đơn vị insulin hòa tan cùng 25 g glucose truyền tĩnh mạch","time_minutes":3,"grade":"critical","rationale":"Đây là phác đồ UKKA cho tăng kali máu nặng."},{"text":"Theo dõi liên tục điện tâm đồ, glucose máu và kali sau điều trị; đồng thời loại bỏ yếu tố gây tăng kali","time_minutes":2,"grade":"recommended","rationale":"Điều trị tạm thời không thay thế việc xử lý nguyên nhân."},{"text":"Chỉ ngừng thuốc nghi gây tăng kali rồi chờ xét nghiệm lại mà không điều trị cấp cứu","time_minutes":0,"grade":"waste","rationale":"Không phù hợp khi tăng kali nặng đã có biến đổi điện tâm đồ."},{"text":"Trì hoãn calcium tĩnh mạch cho đến khi kali giảm sau insulin-glucose","time_minutes":0,"grade":"harmful","rationale":"Người bệnh đang có nguy cơ loạn nhịp đe dọa tính mạng."}],"teaching_explanation":"Tăng kali máu nặng có biến đổi điện tâm đồ là cấp cứu. Mục tiêu ban đầu gồm ổn định màng tế bào cơ tim, chuyển kali vào nội bào, loại kali khỏi cơ thể và xử lý nguyên nhân."}'::jsonb,
  '485833eb67737818a16a124aeef0f11ea4d29087a8bf13faff0a736123db729e'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'noi-than-kinh-004',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-than-kinh-004","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Yếu nửa người đột ngột còn trong cửa sổ tiêu sợi huyết","setting":"giuong","level":"Khó","track":"noi","mode":"tay","specialty":null,"demographics":{"age":64,"sex":"nữ","patient_label":"Người bệnh mô phỏng C"},"presentation":{"intro":"Người bệnh được chuyển vào giường cấp cứu Thần kinh vì đột ngột méo miệng, nói khó và yếu nửa người, thời điểm khởi phát xác định và còn trong cửa sổ tiêu sợi huyết 4,5 giờ.","place":null,"clock":null,"night":false},"vitals":{"hr":86,"sbp":168,"dbp":94,"rr":18,"temperature_c":36.7,"spo2":98},"history":[{"question":"Thời điểm cuối cùng người bệnh còn hoàn toàn bình thường là khi nào?","response":"Thời điểm cuối cùng bình thường được người nhà xác định rõ và hiện vẫn trong cửa sổ 4,5 giờ."},{"question":"Triệu chứng xuất hiện đột ngột hay từ từ?","response":"Đột ngột méo miệng, nói khó và yếu tay chân một bên."},{"question":"Có dùng thuốc chống đông hoặc có chảy máu gần đây không?","response":"Không ghi nhận đang dùng thuốc chống đông."},{"question":"Có đau đầu dữ dội, co giật hoặc mất ý thức lúc khởi phát không?","response":"Không đau đầu dữ dội, không co giật, vẫn tỉnh."},{"question":"Có tiền sử đột quỵ hoặc xuất huyết não không?","response":"Chưa ghi nhận xuất huyết não trước đây."}],"examination":[{"group":"K","item":"Khám vận động","finding":"Yếu rõ tay và chân cùng bên, ảnh hưởng chức năng."},{"group":"K","item":"Khám dây thần kinh sọ","finding":"Liệt mặt trung ương và nói khó."},{"group":"K","item":"Đánh giá ngôn ngữ và tri giác","finding":"Tỉnh, có rối loạn ngôn ngữ nhưng còn làm theo lệnh."},{"group":"K","item":"Khám tim mạch","finding":"Mạch đều tại thời điểm khám, chưa có dấu suy tim cấp."}],"investigations":[{"name":"CT sọ não không cản quang cấp cứu","duration_minutes":15,"result":"Không thấy xuất huyết nội sọ."},{"name":"Glucose máu tại giường","duration_minutes":10,"result":"Không có hạ đường huyết giải thích triệu chứng."},{"name":"Công thức máu và xét nghiệm đông máu khi có chỉ định","duration_minutes":10,"result":"Không phát hiện chống chỉ định rõ với tiêu sợi huyết từ dữ kiện hiện có."},{"name":"Hình ảnh mạch não","duration_minutes":15,"result":"Thực hiện để đánh giá tắc mạch lớn nhưng không làm chậm điều trị tiêu sợi huyết ở người đủ điều kiện."}],"choices":{"diagnosis":{"ydx":["Liệt Todd sau co giật","Xuất huyết não","Hạ đường huyết gây triệu chứng thần kinh","Đột quỵ thiếu máu não cấp còn trong cửa sổ tiêu sợi huyết"]},"actions":["Kích hoạt quy trình đột quỵ và hoàn tất nhanh hình ảnh loại trừ xuất huyết não","Tiến hành tiêu sợi huyết khi còn trong cửa sổ 4,5 giờ và không có chống chỉ định, không trì hoãn chỉ để chờ thêm xét nghiệm không cần thiết","Chờ triệu chứng tự cải thiện hoàn toàn trước khi quyết định tái tưới máu dù thiếu sót thần kinh hiện tại gây tàn tật","Nếu đủ toàn bộ tiêu chuẩn, dùng alteplase tĩnh mạch 0,9 mg/kg, tối đa 90 mg; 10% liều bolus trong 1 phút, phần còn lại truyền trong 60 phút","Cho thuốc chống kết tập tiểu cầu ngay trong lúc đang truyền alteplase"]}}'::jsonb,
  '548eea4f0a821a5a400d039f7dfa8cf9e08ae6ade8ec6e0290156d800caff4ee'
)
on conflict (case_id) do update set
  schema_version = excluded.schema_version,
  data_origin = excluded.data_origin,
  review_status = excluded.review_status,
  public_bundle = excluded.public_bundle,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.answer_keys
  (case_id, answer_key, content_sha256)
values (
  'noi-than-kinh-004',
  '{"schema_version":"1.0.0","case_id":"noi-than-kinh-004","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-noi-than-kinh-004-1","resource_type":"other","source":"American Heart Association/American Stroke Association. 2026 Guideline for the Early Management of Patients With Acute Ischemic Stroke. https://professional.heart.org/en/science-news/2026-guideline-for-the-early-management-of-patients-with-acute-ischemic-stroke/top-things-to-know . Trích: “within the 4.5-hour thrombolytic treatment window”.","title":"American Heart Association/American Stroke Association. 2026 Guideline for the Early Management of Patients With Acute Ischemic Stroke. https://professional.heart.org/en/science-news/2026-guideline-for-the-early-management-of-patients-with-acute-ischemic-stroke/top-things-to-know . Trích: “within the 4.5-hour thrombolytic treatment window”.","organization":null,"year_version":null,"citation":"American Heart Association/American Stroke Association. 2026 Guideline for the Early Management of Patients With Acute Ischemic Stroke. https://professional.heart.org/en/science-news/2026-guideline-for-the-early-management-of-patients-with-acute-ischemic-stroke/top-things-to-know . Trích: “within the 4.5-hour thrombolytic treatment window”.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ais-aha-2019-cb3501f185c2","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/31662037/","title":"American Heart Association/American Stroke Association. Guidelines for the Early Management of Acute Ischemic Stroke, 2019 update. https://www.heart.org/-/-/media/Files/Professional/Quality-Improvement/Get-With-the-Guidelines/Get-With-The-Guidelines-Stroke/2019UpdateAHAASAAISGuidelineSlideDeckrevisedADL12919.pdf . Trích: “IV alteplase (0.9 mg/kg, maximum dose 90 mg over 60 min with initial 10% of dose given as bolus over 1 min)”.","organization":null,"year_version":null,"citation":"American Heart Association/American Stroke Association. Guidelines for the Early Management of Acute Ischemic Stroke, 2019 update. https://www.heart.org/-/-/media/Files/Professional/Quality-Improvement/Get-With-the-Guidelines/Get-With-The-Guidelines-Stroke/2019UpdateAHAASAAISGuidelineSlideDeckrevisedADL12919.pdf . Trích: “IV alteplase (0.9 mg/kg, maximum dose 90 mg over 60 min with initial 10% of dose given as bolus over 1 min)”.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3],"examination_essential_indices":[0,1,2],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"}],"diagnosis_options":{"ydx":[{"text":"Đột quỵ thiếu máu não cấp còn trong cửa sổ tiêu sợi huyết","credit":"full"},{"text":"Xuất huyết não","credit":"none"},{"text":"Hạ đường huyết gây triệu chứng thần kinh","credit":"none"},{"text":"Liệt Todd sau co giật","credit":"none"}]},"action_options":[{"text":"Kích hoạt quy trình đột quỵ và hoàn tất nhanh hình ảnh loại trừ xuất huyết não","time_minutes":3,"grade":"critical","rationale":"Thời gian đến tái tưới máu ảnh hưởng kết cục thần kinh."},{"text":"Nếu đủ toàn bộ tiêu chuẩn, dùng alteplase tĩnh mạch 0,9 mg/kg, tối đa 90 mg; 10% liều bolus trong 1 phút, phần còn lại truyền trong 60 phút","time_minutes":5,"grade":"critical","rationale":"Liều chuẩn AHA/ASA cho alteplase trong đột quỵ thiếu máu não cấp."},{"text":"Tiến hành tiêu sợi huyết khi còn trong cửa sổ 4,5 giờ và không có chống chỉ định, không trì hoãn chỉ để chờ thêm xét nghiệm không cần thiết","time_minutes":5,"grade":"recommended","rationale":"AHA/ASA 2026 tiếp tục khuyến cáo IV thrombolysis trong cửa sổ này."},{"text":"Chờ triệu chứng tự cải thiện hoàn toàn trước khi quyết định tái tưới máu dù thiếu sót thần kinh hiện tại gây tàn tật","time_minutes":0,"grade":"waste","rationale":"Có thể bỏ lỡ cơ hội điều trị hiệu quả."},{"text":"Cho thuốc chống kết tập tiểu cầu ngay trong lúc đang truyền alteplase","time_minutes":0,"grade":"harmful","rationale":"Làm tăng nguy cơ xuất huyết và không phải phối hợp thường quy trong lúc tiêu sợi huyết."}],"teaching_explanation":"Đột quỵ thiếu máu não cấp là cấp cứu phụ thuộc thời gian. Khi thiếu sót thần kinh gây tàn tật, CT không có xuất huyết và người bệnh còn trong cửa sổ điều trị, cần đánh giá tiêu sợi huyết ngay."}'::jsonb,
  '576307cdb500219fe7f16ef8f78e8c4deb4d5e65094a60f19ad453606a13edd2'
)
