insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'noi-huyet-hoc-003',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-huyet-hoc-003","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Giảm tiểu cầu và huyết khối mới sau dùng heparin","setting":"giuong","level":"Khó","track":"noi","mode":"tay","specialty":null,"demographics":{"age":57,"sex":"nam","patient_label":"Người bệnh mô phỏng D"},"presentation":{"intro":"Người bệnh đang điều trị bằng heparin, đến ngày thứ 6 xuất hiện giảm tiểu cầu rõ và đau sưng một chân.","place":null,"clock":null,"night":false},"vitals":{"hr":92,"sbp":122,"dbp":76,"rr":18,"temperature_c":36.8,"spo2":98},"history":[{"question":"Heparin được bắt đầu từ khi nào?","response":"Hiện là ngày thứ 6 kể từ khi bắt đầu heparin."},{"question":"Trước khi dùng heparin số lượng tiểu cầu như thế nào?","response":"Tiểu cầu trước điều trị bình thường và hiện đã giảm hơn một nửa."},{"question":"Có đau sưng chân, đau ngực hoặc khó thở mới xuất hiện không?","response":"Xuất hiện đau và sưng một chân trong khi đang dùng heparin."},{"question":"Có chảy máu niêm mạc hoặc xuất huyết tự nhiên không?","response":"Không có xuất huyết rõ."},{"question":"Có nguyên nhân khác giải thích giảm tiểu cầu như sepsis hoặc thuốc mới không?","response":"Chưa thấy nguyên nhân khác rõ ràng."}],"examination":[{"group":"K","item":"Khám chi dưới","finding":"Một chân sưng, căng và đau hơn bên đối diện."},{"group":"K","item":"Khám da","finding":"Không có xuất huyết lan tỏa; kiểm tra các vị trí tiêm heparin."},{"group":"K","item":"Khám tim phổi","finding":"Chưa có dấu suy hô hấp hoặc sốc."},{"group":"K","item":"Khám thần kinh","finding":"Không có thiếu sót thần kinh khu trú."}],"investigations":[{"name":"Công thức máu nối tiếp","duration_minutes":10,"result":"Tiểu cầu giảm từ 240 xuống 95 ×10^9/L."},{"name":"Tính điểm 4Ts","duration_minutes":10,"result":"Giảm tiểu cầu trên 50%, thời điểm phù hợp sau heparin và có huyết khối mới nên xác suất lâm sàng cao."},{"name":"Miễn dịch PF4-heparin","duration_minutes":15,"result":"Chỉ định khi xác suất lâm sàng không thấp."},{"name":"Siêu âm Doppler tĩnh mạch chân","duration_minutes":15,"result":"Phát hiện huyết khối tĩnh mạch mới."}],"choices":{"diagnosis":{"ydx":["Ban xuất huyết giảm tiểu cầu huyết khối","Giảm tiểu cầu miễn dịch nguyên phát","Giảm tiểu cầu do heparin kèm huyết khối","Giảm tiểu cầu do cường lách"]},"actions":["Truyền tiểu cầu thường quy chỉ vì số lượng tiểu cầu giảm nhưng không có chảy máu đáng kể","Ngừng toàn bộ heparin và khởi thuốc chống đông không phải heparin ở cường độ phù hợp khi xác suất HIT cao","Tiếp tục heparin trong lúc chờ kết quả xét nghiệm dù điểm 4Ts cao và đã xuất hiện huyết khối mới","Tính điểm 4Ts bằng đầy đủ dữ liệu lâm sàng trước khi diễn giải xét nghiệm HIT","Gửi xét nghiệm miễn dịch PF4-heparin và cân nhắc xét nghiệm chức năng theo thuật toán nếu xét nghiệm miễn dịch dương tính"]}}'::jsonb,
  '49d2d5675e82e52aad67862d71a2169833c89f6ba815271e50e93615dd7eb12e'
)
on conflict (case_id) do update set
  schema_version = excluded.schema_version,
  data_origin = excluded.data_origin,
  review_status = excluded.review_status,
  public_bundle = excluded.public_bundle,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.answer_keys
