values (
  'noi-huyet-hoc-003',
  '{"schema_version":"1.0.0","case_id":"noi-huyet-hoc-003","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-noi-huyet-hoc-003-1","resource_type":"other","source":"American Society of Hematology Education Program. Thrombotic anti-PF4 immune disorders: HIT, VITT, and beyond, 2023. https://ashpublications.org/hematology/article/2023/1/1/506391/Thrombotic-anti-PF4-immune-disorders-HIT-VITT-and . Trích: “>50% platelet fall AND a nadir of ≥20 × 10^9/L”; “Platelet fall days 5 to 10 after start of heparin”.","title":"American Society of Hematology Education Program. Thrombotic anti-PF4 immune disorders: HIT, VITT, and beyond, 2023. https://ashpublications.org/hematology/article/2023/1/1/506391/Thrombotic-anti-PF4-immune-disorders-HIT-VITT-and . Trích: “>50% platelet fall AND a nadir of ≥20 × 10^9/L”; “Platelet fall days 5 to 10 after start of heparin”.","organization":null,"year_version":null,"citation":"American Society of Hematology Education Program. Thrombotic anti-PF4 immune disorders: HIT, VITT, and beyond, 2023. https://ashpublications.org/hematology/article/2023/1/1/506391/Thrombotic-anti-PF4-immune-disorders-HIT-VITT-and . Trích: “>50% platelet fall AND a nadir of ≥20 × 10^9/L”; “Platelet fall days 5 to 10 after start of heparin”.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-noi-huyet-hoc-003-2","resource_type":"other","source":"American Society of Hematology 2018 Guidelines for Heparin-Induced Thrombocytopenia. https://ashpublications.org/bloodadvances/article/2/22/3360/16129/American-Society-of-Hematology-2018-guidelines-for . Trích: “discontinuation of heparin and initiation of a non-heparin anticoagulant”.","title":"American Society of Hematology 2018 Guidelines for Heparin-Induced Thrombocytopenia. https://ashpublications.org/bloodadvances/article/2/22/3360/16129/American-Society-of-Hematology-2018-guidelines-for . Trích: “discontinuation of heparin and initiation of a non-heparin anticoagulant”.","organization":null,"year_version":null,"citation":"American Society of Hematology 2018 Guidelines for Heparin-Induced Thrombocytopenia. https://ashpublications.org/bloodadvances/article/2/22/3360/16129/American-Society-of-Hematology-2018-guidelines-for . Trích: “discontinuation of heparin and initiation of a non-heparin anticoagulant”.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,4],"examination_essential_indices":[0,1,2],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"}],"diagnosis_options":{"ydx":[{"text":"Giảm tiểu cầu do heparin kèm huyết khối","credit":"full"},{"text":"Giảm tiểu cầu miễn dịch nguyên phát","credit":"none"},{"text":"Ban xuất huyết giảm tiểu cầu huyết khối","credit":"none"},{"text":"Giảm tiểu cầu do cường lách","credit":"none"}]},"action_options":[{"text":"Tính điểm 4Ts bằng đầy đủ dữ liệu lâm sàng trước khi diễn giải xét nghiệm HIT","time_minutes":3,"grade":"critical","rationale":"ASH khuyến nghị dùng 4Ts thay vì đánh giá cảm tính."},{"text":"Ngừng toàn bộ heparin và khởi thuốc chống đông không phải heparin ở cường độ phù hợp khi xác suất HIT cao","time_minutes":5,"grade":"critical","rationale":"Không chờ xét nghiệm xác nhận mới xử trí ở bệnh cảnh nguy cơ cao."},{"text":"Gửi xét nghiệm miễn dịch PF4-heparin và cân nhắc xét nghiệm chức năng theo thuật toán nếu xét nghiệm miễn dịch dương tính","time_minutes":3,"grade":"recommended","rationale":"Kết hợp xác suất lâm sàng và xét nghiệm làm tăng độ chính xác chẩn đoán."},{"text":"Truyền tiểu cầu thường quy chỉ vì số lượng tiểu cầu giảm nhưng không có chảy máu đáng kể","time_minutes":0,"grade":"waste","rationale":"Không phải xử trí thường quy của HIT."},{"text":"Tiếp tục heparin trong lúc chờ kết quả xét nghiệm dù điểm 4Ts cao và đã xuất hiện huyết khối mới","time_minutes":0,"grade":"harmful","rationale":"Có thể làm tăng nhanh nguy cơ huyết khối, hoại tử chi hoặc tử vong."}],"teaching_explanation":"HIT là tình trạng tăng đông do miễn dịch chứ không đơn thuần là giảm tiểu cầu. Mối liên hệ thời gian với heparin, mức giảm tiểu cầu, huyết khối mới và các nguyên nhân thay thế được tổng hợp bằng điểm 4Ts."}'::jsonb,
  'fb547925e416ab9912d7943b4f0e910358e05d2024b667735121999d0f5385e5'
)
