values (
  'noi-co-xuong-khop-002',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"noi-co-xuong-khop-002","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Sưng nóng đỏ khớp bàn-ngón chân cái khởi phát cấp","setting":"giuong","level":"Trung bình","track":"noi","mode":"tay","specialty":null,"demographics":{"age":49,"sex":"nam","patient_label":"Người bệnh mô phỏng E"},"presentation":{"intro":"Người bệnh nhập khoa Nội vì một khớp bàn-ngón chân cái sưng nóng đỏ đau dữ dội, không có chấn thương.","place":null,"clock":null,"night":false},"vitals":{"hr":88,"sbp":128,"dbp":78,"rr":17,"temperature_c":37.2,"spo2":99},"history":[{"question":"Khớp đau khởi phát như thế nào?","response":"Đau xuất hiện đột ngột, tăng nhanh, chạm nhẹ cũng đau."},{"question":"Trước đây có cơn tương tự không?","response":"Đã từng có cơn đau tương tự rồi tự giảm."},{"question":"Có sốt, rét run hoặc vết thương gần khớp không?","response":"Không sốt cao, không có vết thương gần khớp."},{"question":"Có bệnh thận, sỏi tiết niệu hoặc dùng lợi tiểu không?","response":"Có tăng huyết áp; cần rà soát thuốc đang sử dụng."},{"question":"Có uống nhiều bia rượu hoặc ăn nhiều thực phẩm giàu purine gần đây không?","response":"Có một số yếu tố thuận lợi trong chế độ ăn."}],"examination":[{"group":"K","item":"Khám khớp bàn-ngón chân cái","finding":"Khớp sưng, nóng, đỏ và rất đau khi vận động."},{"group":"K","item":"Đánh giá các khớp khác","finding":"Chưa ghi nhận viêm đa khớp."},{"group":"K","item":"Khám da quanh khớp","finding":"Không thấy vết thương hoặc ổ nhiễm khuẩn da rõ."},{"group":"K","item":"Khám toàn thân","finding":"Chưa có dấu nhiễm trùng huyết."}],"investigations":[{"name":"Chọc hút dịch khớp khi cần xác định chẩn đoán hoặc loại trừ nhiễm khuẩn","duration_minutes":15,"result":"Tinh thể urat monosodium hình kim, lưỡng chiết âm dưới kính phân cực."},{"name":"Nhuộm Gram và cấy dịch khớp khi nghi nhiễm khuẩn","duration_minutes":15,"result":"Không phát hiện vi khuẩn trong tình huống mô phỏng."},{"name":"Acid uric máu","duration_minutes":10,"result":"Có thể tăng."},{"name":"Chức năng thận","duration_minutes":10,"result":"Đánh giá để lựa chọn thuốc chống viêm an toàn."}],"choices":{"diagnosis":{"ydx":["Viêm khớp nhiễm khuẩn","Thoái hóa khớp","Viêm khớp dạng thấp","Cơn gout cấp"]},"actions":["Nếu chọn colchicine và không có chống chỉ định, dùng liều thấp 1,2 mg ngay, sau đó 0,6 mg sau 1 giờ","Dùng colchicine liều cao lặp lại liên tục bất chấp chức năng thận và độc tính","Chọc hút dịch khớp và cấy nếu bệnh cảnh không điển hình hoặc còn nghi viêm khớp nhiễm khuẩn","Điều trị cơn gout bằng colchicine, NSAID hoặc glucocorticoid tùy bệnh kèm và chống chỉ định","Dùng kháng sinh kéo dài khi đã xác định tinh thể gout và không có bằng chứng nhiễm khuẩn"]}}'::jsonb,
  '5e1813c28e2d1513518f53e48cd4403bb5ddeb3cab164a30dcd8d9b43b5969cb'
)
