insert into can_lam_sang_private.answer_keys
  (case_id, answer_key, content_sha256)
values (
  'noi-co-xuong-khop-002',
  '{"schema_version":"1.0.0","case_id":"noi-co-xuong-khop-002","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-noi-co-xuong-khop-002-1","resource_type":"other","source":"American College of Rheumatology. 2020 ACR Guideline for the Management of Gout. https://pmc.ncbi.nlm.nih.gov/articles/PMC10563586/ . Trích: “1.2 mg immediately followed by 0.6 mg an hour later”; “colchicine, NSAIDs, or glucocorticoids ... first-line therapy”.","title":"American College of Rheumatology. 2020 ACR Guideline for the Management of Gout. https://pmc.ncbi.nlm.nih.gov/articles/PMC10563586/ . Trích: “1.2 mg immediately followed by 0.6 mg an hour later”; “colchicine, NSAIDs, or glucocorticoids ... first-line therapy”.","organization":null,"year_version":null,"citation":"American College of Rheumatology. 2020 ACR Guideline for the Management of Gout. https://pmc.ncbi.nlm.nih.gov/articles/PMC10563586/ . Trích: “1.2 mg immediately followed by 0.6 mg an hour later”; “colchicine, NSAIDs, or glucocorticoids ... first-line therapy”.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2],"examination_essential_indices":[0,1,2],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"neutral"},{"index":3,"role":"essential"}],"diagnosis_options":{"ydx":[{"text":"Cơn gout cấp","credit":"full"},{"text":"Viêm khớp nhiễm khuẩn","credit":"none"},{"text":"Viêm khớp dạng thấp","credit":"none"},{"text":"Thoái hóa khớp","credit":"none"}]},"action_options":[{"text":"Điều trị cơn gout bằng colchicine, NSAID hoặc glucocorticoid tùy bệnh kèm và chống chỉ định","time_minutes":3,"grade":"critical","rationale":"ACR khuyến cáo các nhóm này là điều trị đầu tay."},{"text":"Nếu chọn colchicine và không có chống chỉ định, dùng liều thấp 1,2 mg ngay, sau đó 0,6 mg sau 1 giờ","time_minutes":3,"grade":"recommended","rationale":"Đây là liều thấp được ACR khuyến cáo theo liều FDA."},{"text":"Chọc hút dịch khớp và cấy nếu bệnh cảnh không điển hình hoặc còn nghi viêm khớp nhiễm khuẩn","time_minutes":3,"grade":"recommended","rationale":"Không được bỏ sót nhiễm khuẩn khớp."},{"text":"Dùng kháng sinh kéo dài khi đã xác định tinh thể gout và không có bằng chứng nhiễm khuẩn","time_minutes":0,"grade":"waste","rationale":"Không có lợi ích nếu không có nhiễm khuẩn."},{"text":"Dùng colchicine liều cao lặp lại liên tục bất chấp chức năng thận và độc tính","time_minutes":0,"grade":"harmful","rationale":"Tăng nguy cơ tác dụng phụ mà không có lợi ích vượt trội so với phác đồ liều thấp."}],"teaching_explanation":"Cơn gout cấp thường là viêm đơn khớp khởi phát nhanh, nhưng viêm khớp nhiễm khuẩn vẫn là chẩn đoán quan trọng cần loại trừ khi bệnh cảnh không điển hình. Colchicine liều thấp có hiệu quả tương đương với ít tác dụng phụ hơn liều cao."}'::jsonb,
  '8173536a87e2f07ea9697fc41a6297bb16e489b07f897f0ed4c90d552c101760'
)
